window.TADABBUR_ANKABUT = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة العنكبوت (٢٩)، سورةٌ مكّيّةٌ محورُها الابتلاءُ والفتنةُ ومحصُ الإيمان، وقصصُ الأنبياء (نوح، إبراهيم، لوط، شعيب)، ومثلُ العنكبوتِ في وهنِ آلهةِ المشركين، وثمرةُ الجهادِ والصبر؛ فيها «أحسب الناس أن يتركوا أن يقولوا آمنا وهم لا يفتنون». بُدئت بـ«الم». كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":29,"name":"العنكبوت","total_ayahs":69,"audio":[2,6,20,41,45,56,57,64,65,69],"passages":[{"title":"الفتنةُ ومحصُ الإيمانِ وثمرةُ الجهاد","range":[1,13],"theme":"أنّ الإيمانَ لا بدّ له من فتنةٍ تمحّصه، وأنّ العاصيَ لا يفوت الله، وثمرةُ الجهادِ للمجاهد، وبرُّ الوالدين مع تقديمِ حقِّ الله، وكشفُ ضعفاءِ الإيمانِ عند الأذى، وكذبُ من يعد بحملِ الأوزار","verses":[{"n":1,"reflection":{"text":"«الم» — حروفٌ مقطّعةٌ من الحروفِ التي افتُتِحت بها بعضُ السورِ للتنبيهِ على إعجازِ القرآن، الله أعلمُ بمرادِه بها؛ ففي هذا التسليمُ لله في المتشابه؛ فسلّم لله فيما استأثر بعلمه، ولا تتكلّف تأويلَ ما لم يُبيَّن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في المتشابه."},"action":{"text":"سلّم لله فيما استأثر بعلمه من المتشابهِ كالحروفِ المقطّعة، ولا تتكلّف القولَ فيها بلا علم؛ واجعل تسليمك لما لم يتبيّن دأبك، مقبلًا على المحكمِ عاملًا به، فذلك سبيلُ الراسخين في العلم."}},{"n":2,"reflection":{"text":"«أحسب الناس أن يتركوا أن يقولوا آمنا وهم لا يفتنون» — أظنّ الناسُ أن يُتركوا بمجرّدِ قولهم آمنّا دون أن يُختبَروا؟ ففي هذا أنّ الإيمانَ لا بدّ له من ابتلاءٍ يمحّصه؛ فوطّن نفسك على الابتلاء، فالإيمانُ دعوى تُمتحَن بالبلاء، ومن ادّعى الإيمانَ اختُبِر ليتبيّن صدقه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توطينُ النفسِ على الابتلاءِ الممحّصِ للإيمان."},"action":{"text":"وطّن نفسك على أنّ الإيمانَ لا بدّ أن يُبتلى ويُمتحَن، فلا تظنَّ أنك تُترك بمجرّدِ قولك آمنت دون فتنةٍ تمحّصك «أحسب الناس أن يتركوا»؛ فإذا نزل بك ابتلاءٌ في دينك أو مالك أو نفسك فاعلم أنه محكُّ الصدق؛ فاصبر واثبت لتخرج من الفتنةِ مؤمنًا صادقًا؛ فالبلاءُ سنّةٌ ماضيةٌ في المؤمنين، به يتميّز الصادقُ من المدّعي."}},{"n":3,"reflection":{"text":"«ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكاذبين» — ولقد اختبرنا الأممَ قبلهم، فليُظهرنّ الله علمه بالصادقين والكاذبين بما يظهر من أعمالهم؛ ففي هذا أنّ الابتلاءَ سنّةٌ ماضيةٌ لتمييزِ الصادق؛ فاعلم أنّ الفتنةَ سنّةٌ في كلِّ الأمم، بها يتميّز الصادقُ من الكاذب، فكن صادقًا في إيمانك تنجح في الابتلاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ في الإيمانِ لينجح العبدُ في الابتلاء."},"action":{"text":"اعلم أنّ الفتنةَ والابتلاءَ سنّةٌ ماضيةٌ في الأمم كلِّها، بها يميّز الله الصادقَ في إيمانه من الكاذب؛ فاحرص على صدقِ إيمانك في السرّاءِ والضرّاء؛ فإذا امتُحِنت فاثبت واصدق مع الله؛ فالصادقُ يزيده البلاءُ إيمانًا، والكاذبُ يفتضح عند المحنة؛ فراقب صدقك مع الله عند كلِّ اختبار؛ فالنجاحُ في الابتلاءِ بالثباتِ والصدقِ لا بمجرّدِ الدعوى."}},{"n":4,"reflection":{"text":"«أم حسب الذين يعملون السيئات أن يسبقونا ساء ما يحكمون» — أم ظنّ الذين يعملون المعاصيَ أن يفوتونا فلا نقدر عليهم؟ بئس ما يحكمون؛ ففي هذا أنّ العاصيَ لا يفوت الله؛ فلا تغترَّ بالإمهال، فما من عاصٍ يسبق الله أو يعجزه، فالعقوبةُ آتيةٌ وإن تأخّرت، فراقب الله ولا تأمن مكره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالإمهال، فالعاصي لا يفوت الله."},"action":{"text":"لا تغترَّ بإمهالِ الله للعاصين، ولا تظنَّ أنك تسبق الله بمعصيةٍ فتفلت من عقابه «أن يسبقونا ساء ما يحكمون»؛ فما من عاصٍ يعجز الله أو يفوته؛ فالعقوبةُ آتيةٌ ولو تأخّرت؛ فراقب الله في السرِّ والعلن، ولا يخدعنّك حلمُه وإمهاله؛ فبادر بالتوبةِ قبل أن يأخذك أخذَ عزيزٍ مقتدر؛ فمن أيقن أنه لا يفوت الله استقام وحذر المعصية."}},{"n":5,"reflection":{"text":"«من كان يرجو لقاء الله فإن أجل الله لآت وهو السميع العليم» — من كان يرجو ثوابَ لقاءِ الله فليعمل، فإنّ أجلَ الله (وقتَ اللقاء) آتٍ لا محالة، وهو السميعُ العليم؛ ففي هذا حثٌّ على العملِ رجاءَ لقاءِ الله؛ فاعمل لِلقاءِ الله واستعدَّ له، فهو آتٍ قريب، ورجاؤه يحمل على العملِ الصالح، فاجعل لقاءه نصب عينيك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"العملُ رجاءَ لقاءِ الله والاستعدادُ له."},"action":{"text":"اعمل الصالحاتِ رجاءَ لقاءِ الله وثوابه، فإنّ موعدَ اللقاءِ آتٍ لا محالة «فإن أجل الله لآت»؛ فاجعل لقاءَ الله نصب عينيك يحملك على العملِ والاستعداد؛ واعلم أنه السميعُ لأقوالك، العليمُ بأعمالك ونيّاتك؛ فأحسن العملَ مراقبًا له؛ فمن رجا لقاءَ الله عمل له، ومن غفل عنه فرّط؛ فبادر بالزادِ قبل الرحيل، فالأجلُ قريبٌ وإن خُيِّل بعيدًا."}},{"n":6,"reflection":{"text":"«ومن جاهد فإنما يجاهد لنفسه إن الله لغني عن العالمين» — ومن جاهد نفسه وعدوَّه في طاعةِ الله فإنما نفعُ جهادِه لنفسه، إنّ الله لغنيٌّ عن العالمين؛ ففي هذا أنّ ثمرةَ الجهادِ للمجاهدِ نفسه؛ فجاهد نفسك وهواك محتسبًا، فأجرُ جهادك لك، والله غنيٌّ عنك وعن عملك، فما تعمله من خيرٍ يعود نفعه إليك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغني"],"heart_state":{"text":"مجاهدةُ النفسِ محتسبًا، فثمرةُ الجهادِ للمجاهد."},"action":{"text":"جاهد نفسك وهواك وشيطانك في طاعةِ الله، واحتسب أجرك عليه؛ واعلم أنّ ثمرةَ جهادك تعود إليك أنت «فإنما يجاهد لنفسه»؛ فالله غنيٌّ عنك وعن عبادتك، وإنما أمرك بها لنفعك؛ فلا تمنن على الله بطاعتك، ولا تتكاسل عن الجهاد؛ فكلُّ خيرٍ تعمله فلك، وكلُّ شرٍّ فعليك؛ فاجتهد في مجاهدةِ نفسك على الطاعة، فالغنيمةُ لك، والله الغنيُّ الحميد."}},{"n":7,"reflection":{"text":"«والذين آمنوا وعملوا الصالحات لنكفرن عنهم سيئاتهم ولنجزينهم أحسن الذي كانوا يعملون» — والذين آمنوا وعملوا الصالحاتِ لنمحونَّ عنهم سيّئاتهم ولنجزينّهم بأحسنِ أعمالهم؛ ففي هذا وعدُ الله بتكفيرِ السيّئاتِ ومضاعفةِ الأجر؛ فاجمع بين الإيمانِ والعملِ الصالح، فبهما تُكفَّر السيّئاتُ ويُضاعَف الأجر، ففضلُ الله واسعٌ لمن آمن وعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الإيمانِ والعملِ لتكفيرِ السيّئاتِ ومضاعفةِ الأجر."},"action":{"text":"اجمع بين الإيمانِ الصادقِ والعملِ الصالح، فإنّ الله وعد أهلهما بتكفيرِ السيّئاتِ وجزائهم بأحسنِ ما عملوا «لنكفرن عنهم سيئاتهم ولنجزينهم أحسن الذي كانوا يعملون»؛ فاحرص على العملِ الصالحِ المقرونِ بالإيمان، وأبشر بفضلِ الله؛ فمن آمن وعمل غفر الله زلّاته وضاعف حسناته؛ فلا تيأس من ذنبٍ سلف، ولا تفتر عن عملٍ صالح؛ فرحمةُ الله وفضله أوسع من عملك، وجزاؤه أحسنُ من كسبك."}},{"n":8,"reflection":{"text":"«ووصينا الإنسان بوالديه حسنا وإن جاهداك لتشرك بي ما ليس لك به علم فلا تطعهما إلي مرجعكم فأنبئكم بما كنتم تعملون» — وأمرنا الإنسانَ بالإحسانِ إلى والديه، وإن حرصا عليك أن تشرك بي فلا تطعهما في ذلك، إليّ مرجعكم فأخبركم بأعمالكم؛ ففي هذا برُّ الوالدين مع تقديمِ حقِّ الله؛ فبرَّ والديك وأحسن إليهما، ولا تطعهما في معصيةِ الله، فحقُّ الله مقدَّمٌ على كلِّ حقّ، والبرُّ لا يكون بالشرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"برُّ الوالدين مع تقديمِ حقِّ الله على طاعتهما."},"action":{"text":"أحسن إلى والديك وبرَّهما غايةَ البرّ في القولِ والفعلِ والنفقةِ والخدمة؛ لكن إن أمراك بشركٍ أو معصيةٍ لله فلا تطعهما فيها «فلا تطعهما»، مع بقاءِ الإحسانِ إليهما بالمعروف؛ فحقُّ الله مقدَّمٌ على حقِّ كلِّ مخلوق؛ فلا طاعةَ لمخلوقٍ في معصيةِ الخالق؛ فاجمع بين برِّ والديك وطاعةِ ربّك؛ فإذا تعارضا قدّمت حقَّ الله مع لينِ الجانبِ وحسنِ الأدبِ مع الوالدين."}},{"n":9,"reflection":{"text":"«والذين آمنوا وعملوا الصالحات لندخلنهم في الصالحين» — والذين آمنوا وعملوا الصالحاتِ لندخلنّهم في زمرةِ الصالحين؛ ففي هذا شرفُ صحبةِ الصالحين في الآخرة؛ فاعمل الصالحاتِ لتُحشَر مع الصالحين، فمن أحبَّ قومًا وعمل بعملهم حُشِر معهم، فالمرءُ مع من أحبَّ وعمل عمله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ لينالَ العبدُ صحبةَ الصالحين."},"action":{"text":"اعمل الصالحاتِ مع صدقِ الإيمان، لتنال شرفَ الدخولِ في زمرةِ الصالحين في الدنيا والآخرة «لندخلنهم في الصالحين»؛ فأحبَّ الصالحين، واعمل بعملهم، وجالسهم؛ فالمرءُ يُحشَر مع من أحبَّ وعمل عمله؛ فاحرص على أن تكون منهم قولًا وعملًا وسمتًا؛ فمن رافقهم في الدنيا بالعملِ رافقهم في الآخرةِ بالكرامة؛ فاجعل همّك أن تُكتَب في عدادِ عبادِ الله الصالحين."}},{"n":10,"reflection":{"text":"«ومن الناس من يقول آمنا بالله فإذا أوذي في الله جعل فتنة الناس كعذاب الله ولئن جاء نصر من ربك ليقولن إنا كنا معكم أوليس الله بأعلم بما في صدور العالمين» — ومن الناسِ من يقول آمنّا، فإذا أوذي في سبيلِ الله جزع من أذى الناسِ كجزعِه من عذابِ الله فارتدّ، ولئن جاء نصرٌ قال: إنا كنّا معكم، أوليس الله أعلمَ بما في الصدور؟ ففي هذا كشفُ ضعفِ إيمانِ من لا يصبر على الأذى؛ فاصبر على الأذى في سبيلِ الله ولا تجعله كعذابه، فمن جزع من أذى الخلقِ ففرَّ من دينه فقد ضعف يقينه، والله مطّلعٌ على القلوب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الأذى في سبيلِ الله وعدمُ الجزعِ منه."},"action":{"text":"اصبر على أذى الناسِ في سبيلِ دينك، ولا تجعل خوفك من أذاهم كخوفك من عذابِ الله فترتدَّ أو تداهن؛ فذلك حالُ ضعفاءِ الإيمان «جعل فتنة الناس كعذاب الله»؛ فوطّن نفسك على احتمالِ الأذى في طاعةِ الله؛ واعلم أنّ الله مطّلعٌ على ما في صدرك من صدقٍ أو نفاق؛ فلا تكن ممّن يدّعي الإيمانَ في الرخاءِ ويتخلّى عنه في الشدّة؛ فالثباتُ عند الأذى دليلُ صدقِ الإيمان، والفرارُ منه علامةُ ضعفه."}},{"n":11,"reflection":{"text":"«وليعلمن الله الذين آمنوا وليعلمن المنافقين» — وليُظهرنّ الله علمه بالمؤمنين الصادقين وبالمنافقين بما يظهر من أعمالهم عند الابتلاء؛ ففي هذا أنّ البلاءَ يميّز المؤمنَ من المنافق؛ فاعلم أنّ الابتلاءَ محكٌّ يظهر المؤمنَ الصادقَ من المنافقِ المتلوّن، فكن ممّن يثبت عند البلاءِ لا ممّن يتقلّب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ البلاءَ يميّز المؤمنَ من المنافق."},"action":{"text":"اعلم أنّ الابتلاءَ محكٌّ يميّز الله به المؤمنَ الصادقَ من المنافقِ المتلوّن «وليعلمن الله الذين آمنوا وليعلمن المنافقين»؛ فاحرص أن تكون من الثابتين عند البلاءِ لا من المتقلّبين مع الأحوال؛ فراقب نفسك عند الشدائد: أتثبت على الحقِّ أم تتلوّن؟ فالثباتُ برهانُ الإيمان، والتقلّبُ علامةُ النفاق؛ فسل الله الثباتَ، وجاهد نفسك على الصدقِ في السرّاءِ والضرّاء، لتُكتَب في عدادِ المؤمنين الصادقين."}},{"n":12,"reflection":{"text":"«وقال الذين كفروا للذين آمنوا اتبعوا سبيلنا ولنحمل خطاياكم وما هم بحاملين من خطاياهم من شيء إنهم لكاذبون» — وقال الكفارُ للمؤمنين: اتّبعوا ديننا ونحن نحمل عنكم خطاياكم، وما هم بحاملين من خطاياهم شيئًا، إنهم لكاذبون؛ ففي هذا كذبُ من يغري بالمعصيةِ ويعد بحملِ التبعة؛ فلا تصدّق من يزيّن لك الباطلَ ويعد بحملِ وزرك، فلا أحدَ يحمل عنك ذنبك، وكلُّ نفسٍ بما كسبت رهينة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ تصديقِ من يغري بالباطلِ ويعد بحملِ الوزر."},"action":{"text":"لا تصدّق من يزيّن لك المعصيةَ ويغريك بالباطلِ زاعمًا أنه يحمل عنك تبعتها ووزرها؛ فذلك كذبٌ محض «وما هم بحاملين من خطاياهم من شيء»؛ فلا أحدَ يحمل عنك ذنبك يومَ القيامة، ولا يغني عنك من الله شيئًا؛ فكلُّ نفسٍ بما كسبت رهينة؛ فاحذر دعاةَ السوءِ الذين يهوّنون المعصيةَ ويعدون بما لا يملكون؛ فالمسؤوليةُ عليك وحدك، فلا تسلّم دينك لمن يخدعك بوعودٍ كاذبة."}},{"n":13,"reflection":{"text":"«وليحملن أثقالهم وأثقالا مع أثقالهم وليسألن يوم القيامة عما كانوا يفترون» — وليحملنّ أوزارهم وأوزارَ من أضلّوهم مع أوزارهم، وليُسألنّ يومَ القيامةِ عمّا كانوا يفترون؛ ففي هذا أنّ الداعيَ إلى الضلالِ يحمل وزرَه ووزرَ من أضلّه؛ فاحذر أن تكون داعيًا إلى ضلال، فتحمل وزرك ووزرَ من اتّبعك، فالدعوةُ إلى الشرِّ تضاعف الوزر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الدعوةِ إلى الضلالِ المضاعفةِ للوزر."},"action":{"text":"احذر أن تكون داعيًا إلى ضلالٍ أو مزيّنًا لمعصيةٍ أو قدوةً في باطل، فإنك تحمل حينئذٍ وزرك ووزرَ من أضللته أو اتّبعك «وليحملن أثقالهم وأثقالا مع أثقالهم»؛ فمن سنَّ سنّةً سيّئةً فعليه وزرها ووزرُ من عمل بها؛ فتخيّر ما تدعو إليه وما تكون قدوةً فيه؛ فاجعل أثرك في الناسِ خيرًا لا شرًّا؛ فالدعوةُ إلى الهدى تضاعف الأجر، والدعوةُ إلى الضلالِ تضاعف الوزر؛ فانظر أيَّ الأثرين تترك."}}]},{"title":"نوحٌ وإبراهيمُ: الدعوةُ والتوحيدُ وبراهينُ البعث","range":[14,27],"theme":"صبرُ نوحٍ الطويلُ ونجاةُ أصحابِ السفينة، ودعوةُ إبراهيمَ إلى عبادةِ الله وطلبِ الرزقِ منه، وبراهينُ البدءِ والإعادة، ونجاتُه من النار، وهجرتُه وذريّتُه الصالحة","verses":[{"n":14,"reflection":{"text":"«ولقد أرسلنا نوحا إلى قومه فلبث فيهم ألف سنة إلا خمسين عاما فأخذهم الطوفان وهم ظالمون» — ولقد أرسلنا نوحًا إلى قومه فمكث يدعوهم تسعمئةٍ وخمسين سنة، فأخذهم الطوفانُ وهم ظالمون؛ ففي هذا صبرُ نوحٍ الطويلُ على الدعوة؛ فاصبر على الدعوةِ والطاعةِ ولا تستعجل النتائج، فنوحٌ صبر قرونًا، فالداعي يبذل ويصبر، والنتيجةُ بيدِ الله لا بيدِ العجلة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ الطويلُ على الدعوةِ وعدمُ استعجالِ النتائج."},"action":{"text":"اصبر على الدعوةِ إلى الله وعلى الطاعةِ صبرًا طويلًا، ولا تستعجل ظهورَ الثمرة، فقد صبر نوحٌ يدعو قومه تسعمئةٍ وخمسين سنة؛ فالداعي يبذل جهده ويصبر على الإعراضِ والأذى، ويكِل النتيجةَ إلى الله؛ فلا تيأس إن لم ترَ أثرًا سريعًا؛ فأجرك على البذلِ والصبرِ لا على النتيجة؛ فاثبت على دعوتك وطاعتك، محتسبًا صابرًا، فالعاقبةُ للمتّقين، ونصرُ الله آتٍ في وقته لا في وقتك."}},{"n":15,"reflection":{"text":"«فأنجيناه وأصحاب السفينة وجعلناها آية للعالمين» — فأنجينا نوحًا وأصحابَ السفينةِ المؤمنين، وجعلنا السفينةَ (أو القصّةَ) عبرةً للعالمين؛ ففي هذا نجاةُ المؤمنين وجعلُ قصصهم آيةً؛ فاعتبر بنجاةِ المؤمنين وهلاكِ الظالمين، فمن ركب سفينةَ الإيمانِ والطاعةِ نجا، ومن تخلّف عنها غرق، فاركب سفينةَ النجاة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بنجاةِ المؤمنين وركوبُ سفينةِ الإيمان."},"action":{"text":"اعتبر بنجاةِ نوحٍ ومن معه من المؤمنين وهلاكِ الظالمين بالطوفان، فمن ركب سفينةَ الإيمانِ والطاعةِ نجا، ومن تخلّف عنها غرق؛ فاركب سفينةَ النجاةِ بالتمسّكِ بالإيمانِ والعملِ الصالحِ واتّباعِ الرسل؛ واجعل من قصصِ الأنبياءِ آياتٍ وعبرًا تزيدك يقينًا وثباتًا؛ فالله ينجّي أولياءه ويهلك أعداءه؛ فكن ممّن ركب مركبَ الحقِّ والنجاة، لا ممّن تخلّف فهلك مع الهالكين."}},{"n":16,"reflection":{"text":"«وإبراهيم إذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم إن كنتم تعلمون» — واذكر إبراهيمَ إذ قال لقومه: اعبدوا الله واتّقوه، ذلك خيرٌ لكم إن كنتم تعلمون؛ ففي هذا أنّ عبادةَ الله وتقواه خيرُ ما ينصح به؛ فاعبد الله واتّقه، وادعُ الناسَ إلى ذلك، فعبادةُ الله وتقواه خيرُ الأمورِ وأنفعها للعبدِ في دنياه وآخرته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ الله وتقواه، والدعوةُ إليهما."},"action":{"text":"اعبد الله وحده واتّقه في السرِّ والعلن، فذلك خيرُ ما ينبغي أن تحرص عليه وتدعو إليه كدعوةِ إبراهيم «اعبدوا الله واتقوه ذلكم خير لكم»؛ فالعبادةُ والتقوى خيرٌ للعبدِ في دنياه وآخرته، فيهما صلاحُ قلبه وحياته ونجاته؛ فاجعلهما غايتك، وادعُ إليهما أهلك ومن حولك برفقٍ وحكمة؛ فمن عبد الله واتّقاه سعد، ومن أعرض شقي؛ فالخيرُ كلُّه في طاعةِ الله وخشيته."}},{"n":17,"reflection":{"text":"«إنما تعبدون من دون الله أوثانا وتخلقون إفكا إن الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له إليه ترجعون» — إنما تعبدون أصنامًا وتختلقون كذبًا، إنّ ما تعبدون من دونِ الله لا يملك لكم رزقًا، فاطلبوا الرزقَ عند الله واعبدوه واشكروا له، إليه ترجعون؛ ففي هذا بطلانُ عبادةِ ما لا يرزق، وأنّ الرزقَ من الله وحده؛ فاطلب رزقك من الله وحده، واعبده واشكره، فمن بيده الرزقُ هو المستحقُّ للعبادةِ والشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الرزقِ من الله وحده وعبادتُه وشكرُه."},"action":{"text":"اطلب رزقك من الله وحده، فهو الذي يملك الرزقَ لا ما سواه من المخلوقاتِ والأسبابِ العاجزة «فابتغوا عند الله الرزق»؛ فاعبده وحده واشكره على نعمه؛ فمن بيده الرزقُ والنفعُ والضرُّ هو المستحقُّ للعبادةِ والدعاءِ والتوكّل؛ فلا تعلّق قلبك بالأسبابِ ناسيًا مسبّبها؛ بل خذ بالأسبابِ معتمدًا على الله؛ واستحضر أنك إليه ترجع؛ فأخلص له العبادةَ والشكر، فهو الرزّاقُ ذو القوّةِ المتين."}},{"n":18,"reflection":{"text":"«وإن تكذبوا فقد كذب أمم من قبلكم وما على الرسول إلا البلاغ المبين» — وإن تكذّبوا فقد كذّبت أممٌ من قبلكم رسلهم، وما على الرسولِ إلا البلاغُ الواضح؛ ففي هذا تسليةُ النبيِّ وبيانُ أنّ مهمّةَ الرسولِ البلاغ؛ فأدِّ ما عليك من البلاغِ والنصح، ولا تحمل همَّ التكذيب، فليس عليك إلا البلاغ، والهدايةُ بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ البلاغِ وعدمُ حملِ همِّ التكذيب."},"action":{"text":"أدِّ ما عليك من البلاغِ والنصحِ والدعوةِ بوضوح، ولا تحمل همَّ من كذّب أو أعرض، فليس عليك إلا البلاغُ المبين «وما على الرسول إلا البلاغ المبين»؛ فلا يحزنك تكذيبُ المكذّبين، فقد كُذِّب الرسلُ من قبلك؛ فالهدايةُ بيدِ الله لا بيدك؛ فابذل وسعك في التبليغِ والبيان، وكِل القبولَ إلى الله؛ فمن أدّى ما عليه برئت ذمّته، ولا يُطالَب بنتيجةٍ ليست إليه؛ فاصبر وامضِ في دعوتك محتسبًا."}},{"n":19,"reflection":{"text":"«أولم يروا كيف يبدئ الله الخلق ثم يعيده إن ذلك على الله يسير» — أولم يروا كيف يبدأ الله الخلقَ ثم يعيده بعد الموت؟ إنّ ذلك على الله يسير؛ ففي هذا الاستدلالُ ببدءِ الخلقِ على إعادته؛ فتأمّل بدءَ الخلقِ لتوقن بالبعث، فمن قدر على البدءِ قدر على الإعادة، والإعادةُ على الله يسيرة، فلا تشكّ في البعث.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستدلالُ ببدءِ الخلقِ على قدرةِ الله على البعث."},"action":{"text":"تأمّل كيف يبدأ الله الخلقَ من العدم، لتوقن بقدرته على إعادته بعد الموت؛ فمن قدر على الإنشاءِ أولًا فهو على الإعادةِ أقدر، والإعادةُ عليه يسيرة «إن ذلك على الله يسير»؛ فلا يدخلنّ قلبك شكٌّ في البعث؛ فانظر في خلقك وخلقِ ما حولك، وكيف يحيي الله الأرضَ بعد موتها؛ فكلُّ ذلك برهانٌ على البعث؛ فرسّخ يقينك باليومِ الآخر، واعمل له؛ فمن أيقن بالبعثِ استعدَّ له بالعملِ الصالح."}},{"n":20,"reflection":{"text":"«قل سيروا في الأرض فانظروا كيف بدأ الخلق ثم الله ينشئ النشأة الآخرة إن الله على كل شيء قدير» — قل: سيروا في الأرضِ فانظروا كيف بدأ الله الخلق، ثم الله ينشئ النشأةَ الآخرةَ (البعثَ)، إنّ الله على كلِّ شيءٍ قدير؛ ففي هذا الأمرُ بالتأمّلِ في بدءِ الخلقِ دليلًا على البعث؛ فسِر في الأرضِ متأمّلًا بدائعَ خلقِ الله، لتزداد يقينًا بقدرته على البعث، فمن تأمّل قدرةَ الله على البدءِ آمن بقدرته على الإعادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في بدءِ الخلقِ للإيقانِ بقدرةِ الله على البعث."},"action":{"text":"سِر في الأرضِ وتأمّل كيف بدأ الله الخلقَ في أنواعِ المخلوقاتِ من نباتٍ وحيوانٍ وإنسان؛ فذلك يدلّك على قدرته على النشأةِ الآخرةِ والبعث «ثم الله ينشئ النشأة الآخرة»؛ فاجعل نظرك في الكونِ نظرَ تدبّرٍ واعتبارٍ لا نظرَ غفلة؛ فكلّما تأمّلت بدائعَ خلقِ الله ازددت يقينًا بقدرته وبالبعث؛ فهو على كلِّ شيءٍ قدير؛ فرسّخ إيمانك بالقدرةِ والبعثِ بالنظرِ والتأمّل، واستعدَّ للنشأةِ الآخرة."}},{"n":21,"reflection":{"text":"«يعذب من يشاء ويرحم من يشاء وإليه تقلبون» — يعذّب من يشاء بعدله ويرحم من يشاء بفضله، وإليه تُرجَعون؛ ففي هذا أنّ العذابَ والرحمةَ بمشيئةِ الله وحكمته؛ فارجُ رحمةَ الله واخشَ عذابه، واجمع بين الخوفِ والرجاء، فمصيرك إليه، فاعمل لتكون من أهلِ رحمته لا من أهلِ عذابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الخوفِ من العذابِ والرجاءِ في الرحمة."},"action":{"text":"اجمع في قلبك بين الخوفِ من عذابِ الله والرجاءِ في رحمته، فهو «يعذب من يشاء ويرحم من يشاء» بعدله وفضله وحكمته؛ فاعمل لتكون من أهلِ رحمته بالإيمانِ والطاعةِ والتوبة، واحذر أسبابَ عذابه من الكفرِ والمعصيةِ والإصرار؛ ولا تأمن مكره ولا تيأس من رحمته؛ فاستحضر أنّ مرجعك إليه «وإليه تقلبون»؛ فبالخوفِ والرجاءِ يستقيم قلب العبد؛ فسر إلى الله بين خوفٍ يمنعك من المعصيةِ ورجاءٍ يحدوك إلى الطاعة."}},{"n":22,"reflection":{"text":"«وما أنتم بمعجزين في الأرض ولا في السماء وما لكم من دون الله من ولي ولا نصير» — وما أنتم بفائتين الله في الأرضِ ولا في السماء، وما لكم من دونِ الله وليٌّ يتولّاكم ولا نصيرٌ ينصركم؛ ففي هذا إحاطةُ قدرةِ الله وعجزُ العبدِ عن الفرارِ منه؛ فاعلم أنك لا تعجز الله أينما كنت، ولا ناصرَ لك سواه، فالجأ إليه وحده، فمن استنصر بغيره خُذِل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بإحاطةِ قدرةِ الله واللجوءُ إليه وحده."},"action":{"text":"أيقن بأنك لا تفوت الله ولا تعجزه أينما كنت في الأرضِ أو السماء «وما أنتم بمعجزين»؛ فلا مهربَ من الله إلا إليه؛ واعلم أنه لا وليَّ لك يتولّى أمرك ولا نصيرَ ينصرك من دونِ الله؛ فالجأ إليه وحده، واستنصره واستعن به، وتوكّل عليه؛ فمن اعتمد على غيرِ الله خُذِل وضاع؛ فاجعل الله وليَّك وناصرك، خوفًا منه ورجاءً فيه؛ فمن كان الله وليَّه فهو المنصورُ المكفيّ، ومن تخلّى عنه الله فلا ناصرَ له."}},{"n":23,"reflection":{"text":"«والذين كفروا بآيات الله ولقائه أولئك يئسوا من رحمتي وأولئك لهم عذاب أليم» — والذين كفروا بآياتِ الله ولقائه أولئك يئسوا من رحمتي، ولهم عذابٌ أليم؛ ففي هذا أنّ الكفرَ باللقاءِ يورث اليأسَ من الرحمة؛ فآمن بلقاءِ الله وآياتِه لتبقى على الرجاءِ في رحمته، فمن كفر باللقاءِ يئس من الرحمة، والمؤمنُ لا ييأس من رحمةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ باللقاءِ والآياتِ لبقاءِ الرجاءِ في الرحمة."},"action":{"text":"رسّخ إيمانك بآياتِ الله وبلقائه يومَ القيامة، فذلك يبقيك على الرجاءِ في رحمته؛ فإنّ من كفر باللقاءِ والبعثِ يئس من رحمةِ الله «أولئك يئسوا من رحمتي»؛ فلا تيأس من رحمةِ الله أبدًا، فإنّ اليأسَ منها من صفاتِ الكافرين؛ بل اجمع بين الرجاءِ في رحمته والعملِ لِلقائه؛ فمن آمن بلقاءِ الله عمل له ورجا رحمته؛ فاجعل رجاءك في الله كبيرًا، مقرونًا بالإيمانِ والعمل، فرحمتُه وسعت كلَّ شيء."}},{"n":24,"reflection":{"text":"«فما كان جواب قومه إلا أن قالوا اقتلوه أو حرقوه فأنجاه الله من النار إن في ذلك لآيات لقوم يؤمنون» — فما كان جوابُ قومِ إبراهيمَ إلا أن قالوا: اقتلوه أو حرّقوه، فأنجاه الله من النار، إنّ في ذلك لآياتٍ لقومٍ يؤمنون؛ ففي هذا نجاةُ إبراهيمَ من النارِ بحفظِ الله؛ فاعلم أنّ من كان مع الله حفظه ولو من النار، فلا يضرّك كيدُ الأعداءِ إذا كان الله معك، فالنجاةُ بيدِ الله لا بيدِ الخلق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ من كان مع الله حفظه من كلِّ كيد."},"action":{"text":"أيقن بأنّ من كان مع الله بالإيمانِ والتوكّلِ حفظه الله ونجّاه ولو من النارِ المحرقة كما نجّى إبراهيم «فأنجاه الله من النار»؛ فلا يضرّك كيدُ الأعداءِ ولا تدبيرُهم إذا كان الله معك؛ فاجعل اعتمادك على الله وحده عند المحن؛ فالنجاةُ بيده لا بيدِ الخلق؛ فمن صدق توكّله على الله كفاه وحفظه من كلِّ سوء؛ فاثبت على الحقِّ ولو تألّب عليك الأعداء، فالله حافظُ أوليائه وناصرهم، وكيدُ الظالمين مردودٌ عليهم."}},{"n":25,"reflection":{"text":"«وقال إنما اتخذتم من دون الله أوثانا مودة بينكم في الحياة الدنيا ثم يوم القيامة يكفر بعضكم ببعض ويلعن بعضكم بعضا ومأواكم النار وما لكم من ناصرين» — وقال إبراهيم: إنما اتّخذتم الأوثانَ تحابًّا في الدنيا، ثم يومَ القيامةِ يكفر بعضكم ببعضٍ ويلعن بعضكم بعضًا ومأواكم النارُ ولا ناصرَ لكم؛ ففي هذا أنّ مودّةَ أهلِ الباطلِ تنقلب عداوةً يومَ القيامة؛ فلا تبنِ ولاءك على الباطل، فمودّةُ الكفرِ والمعصيةِ تنقلب لعنةً وعداوة، والولاءُ النافعُ ما كان على الإيمانِ والتقوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بناءُ الولاءِ على الإيمانِ لا على الباطل."},"action":{"text":"ابنِ ولاءك ومحبّتك على الإيمانِ والتقوى لا على الباطلِ والمعصية؛ فإنّ مودّةَ أهلِ الباطلِ التي في الدنيا تنقلب يومَ القيامةِ عداوةً ولعنًا وتبرّؤًا «ويلعن بعضكم بعضا»؛ فاختر أخلّاءك على التقوى، فالأخلّاءُ يومئذٍ بعضهم لبعضٍ عدوٌّ إلا المتّقين؛ فلا تجعل رابطتك بالناسِ على الإثمِ والهوى؛ بل على طاعةِ الله؛ فمن تحابَّ في الله دامت مودّتهم في الآخرة، ومن تحابَّ على المعصيةِ صارت وبالًا وعداوةً ونارًا."}},{"n":26,"reflection":{"text":"«فآمن له لوط وقال إني مهاجر إلى ربي إنه هو العزيز الحكيم» — فآمن لإبراهيمَ لوطٌ، وقال إبراهيم: إني مهاجرٌ إلى ربّي (إلى حيث أمرني)، إنه هو العزيزُ الحكيم؛ ففي هذا الهجرةُ في سبيلِ الله فرارًا بالدين؛ فهاجر بدينك إن مُنِعت من إقامته، ففي أرضِ الله سعة، والمهاجرُ إلى الله في معيّةِ العزيزِ الحكيم، فلا يضيع من هاجر إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"الهجرةُ في سبيلِ الله فرارًا بالدين."},"action":{"text":"إذا مُنِعت من إقامةِ دينك أو خشيت الفتنةَ فيه، فهاجر بدينك إلى حيث تعبد الله آمنًا كما فعل إبراهيمُ ولوط «إني مهاجر إلى ربي»؛ ففي أرضِ الله سعة؛ فلا تؤثر البقاءَ في موطنِ الفتنةِ على سلامةِ دينك؛ واعلم أنّ المهاجرَ إلى الله في معيّةِ العزيزِ الحكيمِ الذي لا يضيّع من لجأ إليه؛ فمن ترك شيئًا لله عوّضه خيرًا منه؛ فقدّم دينك على وطنك ومالك إن تعارضا، فالهجرةُ في سبيلِ الله من أعظمِ القُرَب."}},{"n":27,"reflection":{"text":"«ووهبنا له إسحاق ويعقوب وجعلنا في ذريته النبوة والكتاب وآتيناه أجره في الدنيا وإنه في الآخرة لمن الصالحين» — ووهبنا لإبراهيمَ إسحاقَ ويعقوب، وجعلنا في ذريّتِه النبوّةَ والكتاب، وآتيناه أجرَه في الدنيا (بالثناءِ والذريّةِ الصالحة)، وإنه في الآخرةِ لمن الصالحين؛ ففي هذا جزاءُ الله لإبراهيمَ على صبره وهجرته؛ فاعلم أنّ من ضحّى لله عوّضه خيرًا في الدنيا والآخرة، فإبراهيمُ ترك قومه فأبدله الله ذريّةً وأجرًا، فمن هاجر إلى الله لم يخسر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ من ضحّى لله عوّضه في الدارين."},"action":{"text":"أيقن بأنّ من ضحّى لله وترك شيئًا في سبيله عوّضه الله خيرًا منه في الدنيا والآخرة، كما عوّض إبراهيمَ بعد هجرته ذريّةً صالحةً ونبوّةً وثناءً حسنًا وأجرًا «وآتيناه أجره في الدنيا»؛ فلا تخف من التضحيةِ في سبيلِ الله فقرًا أو فوتَ مصلحة؛ فالله لا يضيع أجرَ المحسنين؛ فمن هاجر إليه، وبذل له، وصبر على طاعته، جمع الله له خيرَ الدارين؛ فقدّم لله ما يحبّ يعوّضك ما تحبّ وأكثر؛ فالمعاملةُ معه رابحةٌ لا خسارةَ فيها."}}]},{"title":"لوطٌ مع قومه: الفاحشةُ والنجاةُ والعذاب","range":[28,35],"theme":"إنكارُ لوطٍ ابتداعَ قومه الفاحشةَ والمجاهرةَ بالمنكر، ودعاؤه على المفسدين، وبشارةُ الملائكةِ إبراهيمَ وتطمينُهم لوطًا، ونجاتُه وإهلاكُ قومِه بالرجز، وترْكُ آثارهم آيةً","verses":[{"n":28,"reflection":{"text":"«ولوطا إذ قال لقومه إنكم لتأتون الفاحشة ما سبقكم بها من أحد من العالمين» — واذكر لوطًا إذ قال لقومه: إنكم لتأتون الفاحشةَ التي لم يسبقكم إليها أحدٌ من العالمين؛ ففي هذا إنكارُ لوطٍ لابتداعِ قومه الفاحشة؛ فاحذر الفواحشَ لا سيّما ما ابتُدِع منها، فابتداعُ الشرِّ جريمةٌ مضاعفة، ومن سنَّ سيّئةً حمل وزرها ووزرَ من عمل بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الفواحشِ لا سيّما ابتداعُ الشرّ."},"action":{"text":"احذر الفواحشَ والمنكراتِ كلَّها، وخاصّةً ما تبتدعه من شرٍّ لم يُسبَق إليه، فذلك أعظمُ جرمًا كفعلِ قومِ لوطٍ الذين ابتدعوا الفاحشة «ما سبقكم بها من أحد من العالمين»؛ فمن سنَّ سنّةً سيّئةً حمل وزرها ووزرَ من عمل بها إلى يومِ القيامة؛ فلا تكن أوّلَ من يفتح بابَ شرٍّ أو يُحيي منكرًا؛ بل كن ممّن يميت البدعَ والفواحشَ ويحيي السننَ الصالحة؛ فابتداعُ الخيرِ سنّةٌ حسنة، وابتداعُ الشرِّ سنّةٌ سيّئةٌ يتضاعف بها الإثم."}},{"n":29,"reflection":{"text":"«أئنكم لتأتون الرجال وتقطعون السبيل وتأتون في ناديكم المنكر فما كان جواب قومه إلا أن قالوا ائتنا بعذاب الله إن كنت من الصادقين» — أإنكم لتأتون الرجالَ وتقطعون الطريقَ على الناسِ وتأتون في مجالسكم المنكر؟ فما كان جوابهم إلا أن قالوا: ائتنا بعذابِ الله إن كنت صادقًا؛ ففي هذا تعدادُ منكراتهم واستعجالُهم العذاب؛ فاحذر أن تجاهر بالمنكرِ في المجالس، فالمجاهرةُ بالمعصيةِ أعظمُ من فعلها سرًّا، ولا تستهزئ بوعيدِ الله فتستعجل عذابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من المجاهرةِ بالمنكرِ واستعجالِ العذاب."},"action":{"text":"احذر المجاهرةَ بالمنكراتِ في المجالسِ والأنديةِ والفضاءاتِ العامّة، فإنّ المجاهرةَ بالمعصيةِ أعظمُ إثمًا من فعلها سرًّا، وقد ذمّ الله قومَ لوطٍ بإتيانِ المنكرِ في ناديهم «وتأتون في ناديكم المنكر»؛ فاستتر إن ابتُليت بمعصيةٍ وبادر بالتوبة، ولا تجاهر ولا تفاخر؛ واحذر الاستهزاءَ بوعيدِ الله واستعجالَ عذابه كما فعلوا؛ فمن استخفَّ بالوعيدِ فقد يُعاجَل بالعقوبة؛ فعظّم حرماتِ الله، واستُر نفسك، ولا تجعل المنكرَ مجاهرةً وعادة."}},{"n":30,"reflection":{"text":"«قال رب انصرني على القوم المفسدين» — قال لوط: ربِّ انصرني على القومِ المفسدين؛ ففي هذا لجوءُ لوطٍ إلى الله بالدعاءِ بعد يأسِه من قومه؛ فالجأ إلى الله بالدعاءِ إذا أعياك الإصلاحُ وتمادى المفسدون، فالنصرُ من عند الله، وسلاحُ الداعي الدعاءُ حين تعزّ الحيلة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله بالدعاءِ عند تمادي المفسدين."},"action":{"text":"إذا أعياك إصلاحُ المفسدين وتماديهم في باطلهم، فالجأ إلى الله بالدعاءِ أن ينصرك عليهم كما دعا لوط «رب انصرني على القوم المفسدين»؛ فالدعاءُ سلاحُ المؤمنِ حين تعزّ الحيلةُ ويشتدّ الكرب؛ فارفع أمرك إلى الله بعد بذلِ الوسع في الإصلاح؛ فهو ناصرُ أوليائه على أعدائه؛ فلا تستبطئ النصر، ولا تيأس من روحِ الله؛ فمن صدق في دعائه واستنصاره نصره الله؛ فاجعل الدعاءَ ملاذك عند عجزِ الأسباب."}},{"n":31,"reflection":{"text":"«ولما جاءت رسلنا إبراهيم بالبشرى قالوا إنا مهلكو أهل هذه القرية إن أهلها كانوا ظالمين» — ولما جاءت رسلُنا (الملائكةُ) إبراهيمَ بالبشرى بالولد، قالوا: إنا مهلكو أهلِ قريةِ لوط، إنّ أهلها كانوا ظالمين؛ ففي هذا أنّ الظلمَ سببُ الهلاك؛ فاحذر الظلمَ فإنه سببُ هلاكِ القرى، فما أُهلِكت أمّةٌ إلا بظلمها، فالعدلُ سببُ البقاءِ والظلمُ سببُ الفناء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ الذي هو سببُ هلاكِ الأمم."},"action":{"text":"احذر الظلمَ بكلِّ صوره: ظلمَ النفسِ بالشركِ والمعاصي، وظلمَ الخلقِ بالبغيِ والعدوان؛ فإنّ الظلمَ سببُ هلاكِ القرى والأمم «إن أهلها كانوا ظالمين»؛ فما أُهلِكت أمّةٌ إلا بظلمها؛ فالعدلُ سببُ بقاءِ العمرانِ والأمم، والظلمُ سببُ دمارها؛ فأقم العدلَ في نفسك وأهلك ومن تحت يدك؛ وردَّ المظالمَ، وتُب من كلِّ جور؛ فمن عدل بقي وأمِن، ومن ظلم زال وهلك؛ فالظلمُ ظلماتٌ يومَ القيامة، وعاقبتُه وخيمةٌ في الدنيا والآخرة."}},{"n":32,"reflection":{"text":"«قال إن فيها لوطا قالوا نحن أعلم بمن فيها لننجينه وأهله إلا امرأته كانت من الغابرين» — قال إبراهيم: إنّ فيها لوطًا، قالوا: نحن أعلمُ بمن فيها لننجّينّه وأهله إلا امرأته كانت من الباقين في العذاب؛ ففي هذا شفقةُ إبراهيمَ ونجاةُ لوط، وأنّ القرابةَ لا تنفع مع الكفر؛ فاشفق على عبادِ الله وادفع عنهم ما استطعت، واعلم أنّ النجاةَ بالإيمانِ لا بالنسب، فامرأةُ النبيِّ هلكت بكفرها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشفقةُ على الخلق، وأنّ النجاةَ بالإيمانِ لا النسب."},"action":{"text":"اشفق على عبادِ الله، وادفع عنهم الضرَّ والهلاكَ ما استطعت بالشفاعةِ الحسنةِ والسعيِ في نجاتهم كشفقةِ إبراهيمَ على قومِ لوط؛ واعلم أنّ النجاةَ عند الله بالإيمانِ والعملِ لا بالقرابةِ والنسب، فامرأةُ لوطٍ هلكت مع أنها زوجُ نبيٍّ لأنها كفرت «إلا امرأته كانت من الغابرين»؛ فلا تتّكل على شرفِ نسبٍ أو صلةِ قرابة؛ بل اعمل لنجاتك بنفسك؛ فكلٌّ مرهونٌ بعمله، ولا يغني أحدٌ عن أحدٍ شيئًا؛ فاجمع بين الشفقةِ على الخلقِ والعملِ لنفسك."}},{"n":33,"reflection":{"text":"«ولما أن جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقالوا لا تخف ولا تحزن إنا منجوك وأهلك إلا امرأتك كانت من الغابرين» — ولما جاءت رسلُنا لوطًا ساءه مجيئهم وضاق بهم صدرًا (خوفًا عليهم من قومه)، فقالوا: لا تخف ولا تحزن إنا منجّوك وأهلك إلا امرأتك؛ ففي هذا تطمينُ الملائكةِ للوطٍ عند كربه؛ فاعلم أنّ الله يطمئن أولياءه عند كربهم، فبعد الضيقِ فرج، ومن كان لله كان الله له، فلا يخذل من التجأ إليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يطمئن أولياءه ويفرّج كربهم."},"action":{"text":"أيقن بأنّ الله لا يخذل أولياءه عند كربهم، بل يطمئنهم ويفرّج عنهم كما طمأن الملائكةُ لوطًا عند ضيقه «لا تخف ولا تحزن إنا منجوك»؛ فإذا اشتدّ بك الكربُ وضاق صدرك فأبشر بفرجِ الله؛ فبعد كلِّ ضيقٍ سعة، وبعد كلِّ عسرٍ يسر؛ فمن كان لله بالإيمانِ والطاعةِ كان الله له بالحفظِ والتفريج؛ فلا تخف مع الله، ولا تحزن على ما فات؛ فالجأ إليه، وثِق بتفريجه؛ فهو مؤنسُ الخائفين، ومفرّجُ كربِ المكروبين، ومنجّي أوليائه."}},{"n":34,"reflection":{"text":"«إنا منزلون على أهل هذه القرية رجزا من السماء بما كانوا يفسقون» — إنا منزلون على أهلِ قريةِ لوطٍ عذابًا من السماءِ بسببِ فسقهم وخروجهم عن طاعةِ الله؛ ففي هذا أنّ الفسقَ سببُ نزولِ العذاب؛ فاحذر الفسقَ والخروجَ عن طاعةِ الله، فإنه سببُ العذابِ والعقوبة، والزم الطاعةَ تنجُ من نقمةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الفسقِ الموجبِ لنزولِ العذاب."},"action":{"text":"احذر الفسقَ والخروجَ عن طاعةِ الله والتمرّدَ على شرعه، فإنه سببُ نزولِ العذابِ والعقوباتِ كما نزل الرجزُ على قومِ لوط «بما كانوا يفسقون»؛ فالزم طاعةَ الله واجتنب معاصيه؛ فالمعاصي بريدُ العقوبات، والطاعةُ حصنٌ من النقمات؛ فراقب الله في أمرك ونهيك، وبادر بالتوبةِ من كلِّ فسق؛ فمن أطاع الله أمِن عقابه، ومن فسق عرّض نفسه لنقمته؛ فاجعل الاستقامةَ على أمرِ الله سبيلك للنجاةِ من عذابه في الدنيا والآخرة."}},{"n":35,"reflection":{"text":"«ولقد تركنا منها آية بينة لقوم يعقلون» — ولقد تركنا من قريةِ لوطٍ علامةً واضحةً (آثارَ العذاب) لقومٍ يعقلون؛ ففي هذا أنّ آثارَ الهالكين عبرةٌ لأهلِ العقل؛ فاعتبر بآثارِ الأممِ المهلَكة، فمن عقل اتّعظ بها، والعاقلُ من انتفع بعبرِ من قبله، فالعبرةُ لأولي الألباب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بآثارِ الأممِ المهلَكةِ لأهلِ العقل."},"action":{"text":"اعتبر بآثارِ الأممِ المهلَكةِ التي تركها الله آيةً بيّنةً للعقلاء «آية بينة لقوم يعقلون»؛ فاجعل من أخبارِ الهالكين ومصارعِ الظالمين عبرةً تزيدك خشيةً لله وحذرًا من معصيته؛ فالعاقلُ من اتّعظ بغيره، وانتفع بعبرِ من سبقه؛ فلا تمرَّ على آياتِ الله وعبره مرورَ الغافلين؛ بل تدبّرها بعقلٍ حاضرٍ وقلبٍ واعٍ؛ فمن عقل عن الله آياته انتفع بها، ومن غفل عنها حُرِم ثمرتها؛ فوظّف عقلك في الاعتبارِ والاتّعاظ، فذلك ثمرةُ العقلِ الرشيد."}}]},{"title":"شعيبٌ والأممُ المهلَكةُ، ومثلُ العنكبوت","range":[36,44],"theme":"دعوةُ شعيبٍ وإهلاكُ قومه، وهلاكُ عادٍ وثمودَ وقارونَ وفرعونَ وهامانَ بذنوبهم بعدلِ الله، ومثلُ العنكبوتِ في وهنِ أولياءِ المشركين، وخلقُ الكونِ آيةً","verses":[{"n":36,"reflection":{"text":"«وإلى مدين أخاهم شعيبا فقال يا قوم اعبدوا الله وارجوا اليوم الآخر ولا تعثوا في الأرض مفسدين» — وأرسلنا إلى مدينَ أخاهم شعيبًا فقال: يا قوم اعبدوا الله وارجوا اليومَ الآخر ولا تفسدوا في الأرض؛ ففي هذا جمعُ الدعوةِ بين التوحيدِ ورجاءِ الآخرةِ وترْكِ الفساد؛ فاعبد الله وارجُ الآخرةَ ولا تفسد في الأرض، فهذه أصولُ الصلاحِ التي دعا إليها الأنبياء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ الله ورجاءُ الآخرةِ وترْكُ الفساد."},"action":{"text":"اعبد الله وحده، وارجُ ثوابَ اليومِ الآخرِ فاعمل له، ولا تفسد في الأرضِ بالمعاصي والظلمِ والإضرارِ بالخلق؛ فهذه أصولُ دعوةِ شعيبٍ وسائرِ الأنبياء «اعبدوا الله وارجوا اليوم الآخر ولا تعثوا في الأرض مفسدين»؛ فاجمع في حياتك بين إخلاصِ العبادة، والعملِ للآخرة، والإصلاحِ في الأرض؛ فبها يصلح دينك ودنياك؛ فمن عبد الله ورجا آخرته وأصلح في الأرضِ فقد سلك سبيلَ المرسلين، وفاز بخيرِ الدارين."}},{"n":37,"reflection":{"text":"«فكذبوه فأخذتهم الرجفة فأصبحوا في دارهم جاثمين» — فكذّبوا شعيبًا فأخذتهم الزلزلةُ فأصبحوا في ديارهم موتى هامدين؛ ففي هذا عاقبةُ التكذيب؛ فاحذر تكذيبَ الحقِّ والرسل، فعاقبتُه الهلاك، فما كذّبت أمّةٌ رسولها إلا أُخِذت، فالزم التصديقَ والطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تكذيبِ الحقِّ فعاقبتُه الهلاك."},"action":{"text":"احذر تكذيبَ الحقِّ ودعاةِ الحقّ، فإنّ عاقبةَ التكذيبِ الهلاكُ والدمارُ كما أخذت الرجفةُ قومَ شعيبٍ لمّا كذّبوه «فأصبحوا في دارهم جاثمين»؛ فالزم تصديقَ الحقِّ متى تبيّن، والاستجابةَ لدعاةِ الخير؛ فما كذّبت أمّةٌ نبيَّها إلا استحقّت العقوبة؛ فبادر بالإيمانِ والطاعة، ولا تعاند الحقَّ ولا تستكبر عليه؛ فالتصديقُ والانقيادُ سبيلُ النجاة، والتكذيبُ والإعراضُ سبيلُ الهلاك؛ فاعتبر بمصارعِ المكذّبين."}},{"n":38,"reflection":{"text":"«وعادا وثمود وقد تبين لكم من مساكنهم وزين لهم الشيطان أعمالهم فصدهم عن السبيل وكانوا مستبصرين» — وأهلكنا عادًا وثمودَ وقد ظهرت لكم آثارُ مساكنهم، وزيّن لهم الشيطانُ أعمالهم فصدّهم عن سبيلِ الحقّ وكانوا ذوي عقولٍ وأبصار؛ ففي هذا أنّ العقلَ لا ينفع مع تزيينِ الشيطان؛ فاحذر تزيينَ الشيطانِ للباطل، فلا يعصمك ذكاؤك إن أطعته، فكم من ذي عقلٍ أضلّه الشيطانُ بالتزيين، فاستعذ بالله منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تزيينِ الشيطانِ ولو مع العقلِ والبصيرة."},"action":{"text":"احذر تزيينَ الشيطانِ للباطلِ والمعاصي، فإنه يصدّ عن السبيلِ ولو كان صاحبه ذا عقلٍ وبصيرة، كما زُيِّن لعادٍ وثمود «وكانوا مستبصرين»؛ فلا يغرّنك ذكاؤك أو علمك، فقد يوقعك الشيطانُ في الضلالِ بتحسينِ القبيح؛ فاعرض أعمالك على الشرعِ لا على استحسانِ عقلك؛ واستعذ بالله من الشيطانِ الرجيمِ دائمًا؛ فالعصمةُ في اتّباعِ الوحيِ لا في مجرّدِ العقل؛ فكم من عاقلٍ أهلكه الهوى وتزيينُ الشيطان؛ فاجعل ميزانك الكتابَ والسنّة."}},{"n":39,"reflection":{"text":"«وقارون وفرعون وهامان ولقد جاءهم موسى بالبينات فاستكبروا في الأرض وما كانوا سابقين» — وأهلكنا قارونَ وفرعونَ وهامان، ولقد جاءهم موسى بالبيّناتِ فاستكبروا في الأرضِ وما فاتونا؛ ففي هذا عاقبةُ الكبرِ والاستكبارِ عن الحق؛ فاحذر الكبرَ عن قبولِ الحقّ، فما استكبر أحدٌ إلا أهلكه الله، ولا يفوت الله مستكبر، فالتواضعُ للحقِّ نجاة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ والاستكبارِ عن قبولِ الحق."},"action":{"text":"احذر الكبرَ والاستكبارَ عن قبولِ الحقّ والانقيادِ له، فإنّ الكبرَ أهلك قارونَ وفرعونَ وهامانَ مع ما أوتوا من مالٍ وسلطان «فاستكبروا في الأرض وما كانوا سابقين»؛ فما استكبر أحدٌ على الحقِّ إلا أورده الكبرُ الهلاك؛ ولا يفوت الله مستكبرٌ مهما بلغت قوّته؛ فتواضع للحقِّ متى تبيّن، واقبله ممّن جاء به؛ فالتواضعُ للحقِّ عزٌّ ونجاة، والكبرُ عليه ذلٌّ وهلاك؛ فطهّر قلبك من كبرٍ يمنعك من الإذعانِ للحقّ؛ فالكبرُ أوّلُ ذنبٍ عُصِي الله به."}},{"n":40,"reflection":{"text":"«فكلا أخذنا بذنبه فمنهم من أرسلنا عليه حاصبا ومنهم من أخذته الصيحة ومنهم من خسفنا به الأرض ومنهم من أغرقنا وما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون» — فكلًّا من هؤلاء أخذناه بذنبه: فمنهم من أرسلنا عليه حجارةً، ومنهم من أخذته الصيحة، ومنهم من خسفنا به الأرض، ومنهم من أغرقنا، وما ظلمهم الله ولكن ظلموا أنفسهم؛ ففي هذا عدلُ الله في عقوبةِ كلٍّ بذنبه؛ فاعلم أنّ الله لا يظلم أحدًا، وأنّ ما يصيب العبدَ من عقوبةٍ فبظلمِ نفسه، فلا تظلم نفسك بالمعصية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بعدلِ الله، وأنّ العقوبةَ بظلمِ العبدِ نفسه."},"action":{"text":"آمن بأنّ الله لا يظلم أحدًا مثقالَ ذرّة، وأنّ ما يصيب العبدَ من العقوباتِ إنما هو بسببِ ذنوبه وظلمِه لنفسه «وما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون»؛ فلا تظلم نفسك بالمعاصي والذنوبِ فتجلب عليها العقوبة؛ فكلُّ ما يصيبك من سوءٍ فبكسبِ يديك؛ فراجع نفسك عند البلاء، وتُب من ذنوبك؛ ونزّه ربّك عن الظلم، وأحسن الظنَّ بعدله؛ فمن حفظ نفسه من الظلمِ حفظه الله من العقوبة؛ فالعقوباتُ آثارُ الذنوب، فاجتنبها تسلم."}},{"n":41,"reflection":{"text":"«مثل الذين اتخذوا من دون الله أولياء كمثل العنكبوت اتخذت بيتا وإن أوهن البيوت لبيت العنكبوت لو كانوا يعلمون» — مثلُ الذين اتّخذوا من دونِ الله أولياءَ يتوكّلون عليهم كمثلِ العنكبوتِ اتّخذت بيتًا واهيًا، وإنّ أوهنَ البيوتِ بيتُ العنكبوت، لو كانوا يعلمون؛ ففي هذا بيانُ وهنِ ما يتعلّق به المشركون؛ فلا تتّخذ من دونِ الله وليًّا تعتمد عليه، فالاعتمادُ على غيرِ الله كبيتِ العنكبوتِ لا يقي ولا ينفع، فالركنُ الوثيقُ هو الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاعتمادِ على غيرِ الله فهو كبيتِ العنكبوتِ الواهن."},"action":{"text":"لا تتّخذ من دونِ الله وليًّا تعتمد عليه وتتوكّل عليه من مخلوقٍ أو مالٍ أو جاه، فإنّ الاعتمادَ على غيرِ الله واهٍ ضعيفٌ كبيتِ العنكبوتِ الذي هو أوهنُ البيوت «وإن أوهن البيوت لبيت العنكبوت»؛ فالركنُ الوثيقُ الذي لا ينهار هو الله وحده؛ فاجعل توكّلك واعتمادك عليه؛ فمن تعلّق بغيرِ الله انهار به معتمَده أحوجَ ما يكون إليه؛ ومن اعتمد على الله كفاه وأغناه؛ فتفقّد قلبك: على من يتّكل؟ فلا وليَّ ولا نصيرَ ولا معتمَدَ حقٌّ إلا الله."}},{"n":42,"reflection":{"text":"«إن الله يعلم ما يدعون من دونه من شيء وهو العزيز الحكيم» — إنّ الله يعلم ما يدعون من دونه من شيءٍ لا حقيقةَ له ولا نفع، وهو العزيزُ الحكيم؛ ففي هذا إحاطةُ علمِ الله ببطلانِ آلهتهم؛ فاعلم أنّ الله يعلم بطلانَ كلِّ ما يُعبَد سواه، فلا تدعُ إلا الله، فهو العزيزُ القادرُ الحكيمُ في تدبيره، وما سواه عاجزٌ لا يُدعى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"إفرادُ الله بالدعاءِ لعلمِه ببطلانِ ما سواه."},"action":{"text":"أفرد الله بالدعاءِ والعبادة، فهو يعلم أنّ كلَّ ما يُدعى من دونه باطلٌ لا حقيقةَ لنفعه ولا ضرّه «إن الله يعلم ما يدعون من دونه من شيء»؛ فلا تصرف دعاءك ورجاءك إلى سواه؛ فهو العزيزُ الذي لا يُغلَب، الحكيمُ الذي لا يعبث؛ وما سواه عاجزٌ لا يملك لنفسه ولا لغيره شيئًا؛ فاجعل دعاءك خالصًا لله وحده، وتوكّلك عليه؛ فمن دعا غيره فقد دعا من لا يسمع ولا يستجيب ولا ينفع؛ فالعبادةُ والدعاءُ حقٌّ للعزيزِ الحكيمِ وحده."}},{"n":43,"reflection":{"text":"«وتلك الأمثال نضربها للناس وما يعقلها إلا العالمون» — وتلك الأمثالُ (كمثلِ العنكبوت) نضربها للناسِ لتقريبِ المعاني، وما يفهمها حقَّ الفهمِ إلا العالمون؛ ففي هذا فضلُ العلمِ في فهمِ أمثالِ القرآن؛ فاطلب العلمَ لتفهم أمثالَ الله وتنتفع بها، فالأمثالُ حكمةٌ لا يدركها إلا أهلُ العلم، فالعلمُ مفتاحُ فهمِ كتابِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العلمِ لفهمِ أمثالِ القرآنِ والانتفاعِ بها."},"action":{"text":"اطلب العلمَ النافعَ لتفهم أمثالَ القرآنِ وحِكَمه وتنتفع بها، فإنّ الله يضرب الأمثالَ للناسِ ولا يعقلها حقَّ العقلِ إلا العالمون «وما يعقلها إلا العالمون»؛ فاجتهد في تعلّمِ كتابِ الله وتدبّرِ أمثاله؛ فالأمثالُ تقرّب المعانيَ وتجليها، لكن لا يدرك مغزاها إلا من رزقه الله علمًا وفهمًا؛ فاحرص على مجالسِ العلمِ وتدبّرِ القرآن؛ فبالعلمِ تفتح كنوزَ الأمثالِ والحكم؛ فالعلمُ نورٌ يهديك إلى مقاصدِ كلامِ الله؛ فلا تكن من الغافلين الذين تمرّ بهم الأمثالُ بلا اعتبار."}},{"n":44,"reflection":{"text":"«خلق الله السماوات والأرض بالحق إن في ذلك لآية للمؤمنين» — خلق الله السماواتِ والأرضَ بالحقِّ والحكمةِ لا عبثًا، إنّ في ذلك لآيةً للمؤمنين على قدرته ووحدانيته؛ ففي هذا الاستدلالُ بخلقِ الكونِ على الخالق؛ فتأمّل خلقَ السماواتِ والأرضِ لتزداد إيمانًا، فمن نظر في الكونِ بعينِ المؤمنِ رأى فيه آياتِ الخالقِ الحكيم، فالكونُ كتابٌ مفتوحٌ لأهلِ الإيمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في خلقِ الكونِ لزيادةِ الإيمان."},"action":{"text":"تأمّل في خلقِ السماواتِ والأرضِ وما فيهما من إحكامٍ وحكمة، فقد خلقهما الله بالحقِّ لا عبثًا؛ فذلك آيةٌ للمؤمنين على قدرةِ الله ووحدانيته وحكمته «إن في ذلك لآية للمؤمنين»؛ فاجعل نظرك في الكونِ نظرَ تدبّرٍ يزيدك إيمانًا وخشيةً وتعظيمًا لله؛ فالكونُ كتابٌ مفتوحٌ يقرأ آياتِه أهلُ الإيمان؛ فكلّما نظرت إلى سماءٍ أو أرضٍ أو مخلوقٍ فتذكّر عظمةَ خالقه؛ فمن نظر بعينِ الاعتبارِ ازداد يقينًا، ومن نظر بعينِ الغفلةِ حُرِم؛ فاقرأ آياتِ الله في الآفاقِ لتقوى صلتك به."}}]},{"title":"الصلاةُ والقرآنُ ووحيُه، وجدالُ أهلِ الكتاب، واستعجالُ العذاب","range":[45,55],"theme":"تلاوةُ الكتابِ وإقامةُ الصلاةِ الناهيةِ عن الفحشاء، والجدالُ بالتي هي أحسن، وأُمّيّةُ النبيِّ دليلَ صدقِ القرآن، وكفايةُ القرآنِ آيةً، واستعجالُ العذابِ وإحاطتُه بالكافرين","verses":[{"n":45,"reflection":{"text":"«اتل ما أوحي إليك من الكتاب وأقم الصلاة إن الصلاة تنهى عن الفحشاء والمنكر ولذكر الله أكبر والله يعلم ما تصنعون» — اتلُ ما أُوحي إليك من القرآنِ واعمل به، وأقم الصلاةَ، إنّ الصلاةَ تنهى عن الفحشاءِ والمنكر، ولذكرُ الله أكبر، والله يعلم ما تصنعون؛ ففي هذا فضلُ التلاوةِ والصلاةِ والذكر؛ فاتلُ القرآنَ وأقم الصلاةَ حقَّ إقامتها، فالصلاةُ الخاشعةُ تنهى صاحبها عن الفحشاءِ والمنكر، وذكرُ الله أعظمُ ما في الصلاةِ وأكبرُ القُرَب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إقامةُ الصلاةِ وتلاوةُ القرآنِ وذكرُ الله."},"action":{"text":"اتلُ القرآنَ متدبّرًا عاملًا به، وأقم الصلاةَ بأركانها وخشوعها؛ فإنّ الصلاةَ المقامةَ حقَّ إقامتها تنهى صاحبها عن الفحشاءِ والمنكر «إن الصلاة تنهى عن الفحشاء والمنكر»؛ فإن لم تنهك صلاتك فراجع خشوعك وإقامتك لها؛ واعلم أنّ ذكرَ الله أكبرُ القُرَبِ وأعظمها؛ فاعمر لسانك وقلبك بذكرِ الله؛ واستحضر أنّ الله يعلم ما تصنع؛ فاجعل الصلاةَ والتلاوةَ والذكرَ عمادَ يومك؛ فبها يصلح قلبك، وتُعصَم من المعاصي، وتقوى صلتك بالله؛ فمن أقام الصلاةَ حقًّا استقامت حياته."}},{"n":46,"reflection":{"text":"«ولا تجادلوا أهل الكتاب إلا بالتي هي أحسن إلا الذين ظلموا منهم وقولوا آمنا بالذي أنزل إلينا وأنزل إليكم وإلهنا وإلهكم واحد ونحن له مسلمون» — ولا تجادلوا أهلَ الكتابِ إلا بالطريقةِ الأحسنِ من اللينِ والحجّة، إلا الظالمين المعتدين منهم، وقولوا: آمنّا بما أُنزل إلينا وإليكم وإلهُنا وإلهكم واحدٌ ونحن له مسلمون؛ ففي هذا أدبُ الجدالِ بالتي هي أحسن؛ فجادل المخالفَ بالحسنى واللينِ والحجّة، لا بالغلظةِ والسبّ، فالجدالُ الحسنُ أدعى للقبول، إلا من ظلم واعتدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجدالُ بالتي هي أحسنُ لا بالغلظة."},"action":{"text":"جادل المخالفين ولا سيّما أهلَ الكتابِ بالطريقةِ الأحسنِ من اللينِ في القولِ وقوّةِ الحجّةِ وحسنِ العرض، لا بالغلظةِ والسبِّ والتشفّي «ولا تجادلوا أهل الكتاب إلا بالتي هي أحسن»؛ فالجدالُ الحسنُ أدعى لقبولِ الحقِّ وتأليفِ القلوب؛ فاحرص على بيانِ المشتركِ ثم بيانِ الحقّ برفق؛ إلا من ظلم واعتدى وعاند فله ما يستحقّ؛ فاجعل هدفك من الحوارِ الهدايةَ لا الغلبةَ والانتقام؛ فالكلمةُ الطيّبةُ والحجّةُ البيّنةُ تفتحان القلوب؛ فالزم الرفقَ والإنصافَ في مجادلتك، فالغلظةُ تنفّر عن الحقّ."}},{"n":47,"reflection":{"text":"«وكذلك أنزلنا إليك الكتاب فالذين آتيناهم الكتاب يؤمنون به ومن هؤلاء من يؤمن به وما يجحد بآياتنا إلا الكافرون» — وكذلك أنزلنا إليك القرآن، فالذين آتيناهم الكتابَ (المنصفون) يؤمنون به، ومن أهلِ مكةَ من يؤمن به، وما يجحد بآياتنا إلا الكافرون المعاندون؛ ففي هذا أنّ المنصفَ يؤمن والجاحدَ يعاند؛ فكن من المؤمنين المنصفين لا من الجاحدين، فالجحودُ بعد وضوحِ الآياتِ كفرٌ وعناد، والإيمانُ بها توفيق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الكونُ من المؤمنين المنصفين لا من الجاحدين."},"action":{"text":"كن من المؤمنين المنصفين الذين يؤمنون بآياتِ الله متى تبيّنت لهم، لا من الجاحدين المعاندين «وما يجحد بآياتنا إلا الكافرون»؛ فالجحودُ بالحقِّ بعد وضوحِ آياته كفرٌ وعناد؛ فإذا تبيّن لك حقٌّ فأذعن له وآمن؛ ولا تكابر ولا تعاند؛ فالمنصفُ يقبل الحقَّ ولو خالف هواه، والجاحدُ يردّه ولو قامت عليه البراهين؛ فطهّر قلبك من العنادِ والكبر؛ واطلب الحقَّ بقلبٍ منفتحٍ منصف؛ فمن آمن بآياتِ الله نال التوفيق، ومن جحدها بعد ظهورها حُرِم؛ فاجعل الإنصافَ والإذعانَ للحقِّ دأبك."}},{"n":48,"reflection":{"text":"«وما كنت تتلو من قبله من كتاب ولا تخطه بيمينك إذا لارتاب المبطلون» — وما كنت يا محمدُ تقرأ كتابًا قبل القرآنِ ولا تكتبه بيدك، ولو كنت كذلك لشكَّ المبطلون في مصدره؛ ففي هذا أنّ أُمّيّةَ النبيِّ دليلُ صدقِ القرآن؛ فازدد يقينًا بأنّ القرآنَ وحيٌ، فما جاء به رجلٌ أميٌّ لم يقرأ ولم يكتب إلا وحيًا من الله، فأُمّيّتُه ﷺ برهانٌ على صدقِ ما جاء به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الازديادُ يقينًا بصدقِ القرآنِ من أُمّيّةِ النبيّ."},"action":{"text":"ازدد يقينًا بأنّ القرآنَ وحيٌ من الله، فإنّ النبيَّ ﷺ كان أُمّيًّا لا يقرأ كتابًا ولا يكتب بيده «وما كنت تتلو من قبله من كتاب ولا تخطه بيمينك»؛ فكيف يأتي أُمّيٌّ بهذا الكتابِ المعجزِ لولا الوحي؟ فأُمّيّتُه ﷺ برهانٌ قاطعٌ على صدقِ رسالته وأنّ القرآنَ من عند الله؛ فتأمّل هذه الحجّة، وردَّ بها على المبطلين المرتابين؛ فاثبت على الإيمانِ بالقرآن، واتّبع ما فيه؛ فمصدرُه الإلهيُّ يوجب تعظيمه والعملَ به؛ فمن تدبّر أدلّةَ صدقِ القرآنِ ازداد إيمانًا ويقينًا."}},{"n":49,"reflection":{"text":"«بل هو آيات بينات في صدور الذين أوتوا العلم وما يجحد بآياتنا إلا الظالمون» — بل القرآنُ آياتٌ واضحاتٌ محفوظةٌ في صدورِ العلماءِ المؤمنين، وما يجحد بآياتنا إلا الظالمون؛ ففي هذا شرفُ حفظِ القرآنِ في الصدورِ وأنّ الجحودَ ظلم؛ فاحفظ القرآنَ في صدرك، فحفظُه شرفٌ وحفظٌ له، ولا تجحد آياتِ الله فالجحودُ ظلم، فكن من حَمَلةِ القرآنِ العاملين به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ القرآنِ في الصدرِ والعملُ به وترْكُ الجحود."},"action":{"text":"احرص على حفظِ القرآنِ في صدرك ولو بعضه، فحفظُه شرفٌ لصاحبه وحفظٌ للكتابِ في الصدور «بل هو آيات بينات في صدور الذين أوتوا العلم»؛ واعمل بما تحفظ؛ ولا تجحد شيئًا من آياتِ الله، فالجحودُ بها بعد وضوحها ظلمٌ عظيم «وما يجحد بآياتنا إلا الظالمون»؛ فكن من حَمَلةِ القرآنِ العلماءِ العاملين به؛ فاجعل من وردك حفظًا وتدبّرًا وعملًا؛ فأهلُ القرآنِ هم أهلُ الله وخاصّته؛ فاطلب هذا الشرفَ، واحذر أن تكون من الجاحدين الظالمين لأنفسهم بردِّ الحقّ."}},{"n":50,"reflection":{"text":"«وقالوا لولا أنزل عليه آيات من ربه قل إنما الآيات عند الله وإنما أنا نذير مبين» — وقالوا: هلّا أُنزِلت عليه آياتٌ (كآياتِ موسى) من ربّه؟ قل: إنما الآياتُ عند الله ينزّلها كيف شاء، وإنما أنا نذيرٌ مبين؛ ففي هذا أنّ الآياتِ بيدِ الله لا بيدِ الرسول؛ فاعلم أنّ الآياتِ والمعجزاتِ بيدِ الله يجريها بحكمته، ومهمّةُ الرسولِ الإنذارُ والبلاغ، فلا تعلّق إيمانك باقتراحِ الآيات، بل بالبرهانِ القائم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ الآياتِ بيدِ الله، ومهمّةُ الرسولِ الإنذار."},"action":{"text":"اعلم أنّ الآياتِ والمعجزاتِ بيدِ الله وحده ينزّلها متى شاء وكيف شاء بحكمته، لا بيدِ الرسولِ ولا باقتراحِ المعاندين «إنما الآيات عند الله»؛ ومهمّةُ الرسولِ الإنذارُ والبلاغُ المبين؛ فلا تعلّق إيمانك باقتراحِ آياتٍ معيّنة، بل آمن بما قام عليه البرهان؛ ولا تتعنّت بطلبِ الآياتِ بعد وضوحِ الحجّة؛ فقد آتاك الله أعظمَ آية: القرآن؛ فاكتفِ بالبراهينِ القائمة، ولا تكن كالمعاندين الذين يقترحون الآياتِ ثم لا يؤمنون؛ فالهدايةُ في اتّباعِ ما تبيّن، لا في التعنّتِ والاقتراح."}},{"n":51,"reflection":{"text":"«أولم يكفهم أنا أنزلنا عليك الكتاب يتلى عليهم إن في ذلك لرحمة وذكرى لقوم يؤمنون» — أولم يكفهم آيةً أنا أنزلنا عليك القرآنَ يُتلى عليهم؟ إنّ في ذلك لرحمةً وتذكرةً لقومٍ يؤمنون؛ ففي هذا أنّ القرآنَ أعظمُ آية؛ فاكتفِ بالقرآنِ آيةً ورحمةً وذكرى، فمن لم يكفه القرآنُ لم تكفه آية، وفيه من البراهينِ والرحمةِ ما يُغني عن كلِّ اقتراح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاكتفاءُ بالقرآنِ آيةً ورحمةً وذكرى."},"action":{"text":"اكتفِ بالقرآنِ آيةً كبرى ورحمةً وتذكرة، فهو أعظمُ معجزةٍ وأبقاها، يُتلى عليك في كلِّ حين «أولم يكفهم أنا أنزلنا عليك الكتاب يتلى عليهم»؛ فمن لم يكفه القرآنُ برهانًا لم تكفه آية؛ ففيه من الحججِ والهدى والرحمةِ ما يُغني عن كلِّ اقتراح؛ فأقبل عليه تلاوةً وتدبّرًا وعملًا؛ واجعله رحمتك وذكراك؛ فمن تدبّره وجد فيه شفاءَ قلبه وجلاءَ همّه وهدايةَ أمره؛ فلا تطلب آيةً وراءه، واعكف على استخراجِ كنوزه؛ فالقرآنُ رحمةٌ وذكرى لمن آمن به وانتفع."}},{"n":52,"reflection":{"text":"«قل كفى بالله بيني وبينكم شهيدا يعلم ما في السماوات والأرض والذين آمنوا بالباطل وكفروا بالله أولئك هم الخاسرون» — قل: كفى بالله شهيدًا بيني وبينكم، يعلم ما في السماواتِ والأرض، والذين آمنوا بالباطلِ وكفروا بالله أولئك هم الخاسرون؛ ففي هذا الاكتفاءُ بشهادةِ الله، وخسرانُ من آمن بالباطل؛ فاكتفِ بشهادةِ الله على صدقك، واحذر أن تؤمن بباطلٍ وتكفر بالحقّ، فذلك هو الخسرانُ المبين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاكتفاءُ بشهادةِ الله والحذرُ من الإيمانِ بالباطل."},"action":{"text":"اكتفِ بشهادةِ الله على صدقك وحقّك، فهو أعظمُ شاهدٍ يعلم ما في السماواتِ والأرض «كفى بالله بيني وبينكم شهيدا»؛ فمتى علم الله صدقك فحسبك ذلك ولو خذلك الخلق؛ واحذر أشدَّ الحذرِ أن تؤمن بباطلٍ (كالشركِ والخرافةِ والأهواء) وتكفر بالحقّ، فذلك هو الخسرانُ المبين «أولئك هم الخاسرون»؛ فزِن معتقداتك ومواقفك بميزانِ الوحي؛ فآمن بالحقِّ واكفر بالباطل؛ فمن قلب الأمرَ فآمن بالباطلِ وكفر بالحقِّ فقد خسر دنياه وآخرته؛ فاجعل إيمانك بالحقِّ وحده، وأشهد الله على صدقك."}},{"n":53,"reflection":{"text":"«ويستعجلونك بالعذاب ولولا أجل مسمى لجاءهم العذاب وليأتينهم بغتة وهم لا يشعرون» — ويستعجلونك بالعذابِ استهزاءً، ولولا أجلٌ محدّدٌ عند الله لجاءهم العذابُ عاجلًا، وليأتينّهم فجأةً وهم غافلون؛ ففي هذا أنّ تأخّرَ العذابِ لأجلٍ مسمًّى لا لعجز؛ فلا تستعجل عذابَ الله ولا تأمن مجيئه بغتة، فالإمهالُ لأجلٍ مقدّر، والعذابُ قد يأتي فجأةً، فبادر بالتوبةِ واليقظة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ استعجالِ العذابِ والحذرُ من مجيئه بغتة."},"action":{"text":"لا تستعجل عذابَ الله ولا تستهزئ بوعيده كما فعل المكذّبون، ولا تأمن أن يأتيك بغتةً وأنت غافل؛ فإنّ تأخّرَ العذابِ إنما هو لأجلٍ مسمًّى عند الله لا لعجزٍ عنه «ولولا أجل مسمى لجاءهم العذاب»؛ فإذا رأيت إمهالَ الله للعاصين فلا تظنّه إهمالًا؛ فالعذابُ قد يأتي فجأةً حين لا يُشعَر به؛ فبادر بالتوبةِ والاستعدادِ واليقظةِ الدائمة؛ فمن عاش مستعدًّا لم تفجأه العقوبةُ على غِرّة؛ فاجعل قلبك بين خوفٍ من مباغتةِ الأجلِ ورجاءٍ في رحمةِ الله؛ فالغافلُ يُؤخَذ بغتةً، والمستعدُّ آمن."}},{"n":54,"reflection":{"text":"«يستعجلونك بالعذاب وإن جهنم لمحيطة بالكافرين» — يستعجلونك بالعذابِ، وإنّ جهنمَ لمحيطةٌ بالكافرين لا مفرَّ لهم منها؛ ففي هذا أنّ العذابَ محيطٌ بالكافرين لا محالة؛ فاحذر أن تكون من الكافرين الذين أحاطت بهم جهنم، فالعذابُ محدقٌ بهم وإن استعجلوه استهزاءً، فبادر بالإيمانِ والتوبةِ قبل الإحاطة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من إحاطةِ جهنمَ بالكافرين والمبادرةُ بالإيمان."},"action":{"text":"احذر أن تكون من الكافرين الذين أحاطت بهم جهنمُ من كلِّ جانبٍ فلا مفرَّ لهم منها «وإن جهنم لمحيطة بالكافرين»؛ فالعذابُ محدقٌ بهم وإن استعجلوه استهزاءً وهم لا يشعرون بقربه؛ فبادر بالإيمانِ الصادقِ والتوبةِ النصوحِ والعملِ الصالحِ قبل أن يحيط بك العذاب؛ فلا تسوّف بالتوبةِ ولا تغترَّ بالإمهال؛ فمن آمن وعمل نجا من الإحاطة، ومن كفر وأصرَّ أحاطت به النار؛ فاجعل همّك النجاةَ من هذا المصير المحيط، بالإقبالِ على الله من الآن."}},{"n":55,"reflection":{"text":"«يوم يغشاهم العذاب من فوقهم ومن تحت أرجلهم ويقول ذوقوا ما كنتم تعملون» — يومَ يغطّيهم العذابُ من فوقهم ومن تحت أرجلهم، ويقال لهم: ذوقوا جزاءَ ما كنتم تعملون؛ ففي هذا هولُ إحاطةِ العذابِ بالكافرين وأنّ الجزاءَ من جنسِ العمل؛ فاستحضر هولَ ذلك اليوم، واعمل صالحًا لتنجو منه، فالجزاءُ من جنسِ العمل، فما تعمله اليومَ تذوقه غدًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ هولِ العذابِ والعملُ للنجاةِ منه."},"action":{"text":"استحضر هولَ يومٍ يغشى العذابُ فيه الكافرين من فوقهم ومن تحت أرجلهم، ويُقال لهم توبيخًا: «ذوقوا ما كنتم تعملون»؛ فاجعل هذا المشهدَ حافزًا لك على العملِ الصالحِ واجتنابِ المعاصي؛ فالجزاءُ من جنسِ العمل، وما تقدّمه اليومَ من خيرٍ أو شرٍّ تذوق ثمرته غدًا؛ فبادر بالأعمالِ التي تُنجيك من هذا العذابِ المحيط؛ واحذر ما يورده؛ فمن عمل للنجاةِ نجا، ومن غفل وأصرَّ ذاق وبالَ أمره؛ فاعمل لآخرتك عملَ من يرى الجزاء، فالعملُ الصالحُ هو الزادُ ليومِ اللقاء."}}]},{"title":"سعةُ الأرضِ وذوقُ الموتِ وجزاءُ الصابرين، وأدلةُ التوحيدِ وثمرةُ الجهاد","range":[56,69],"theme":"الأمرُ بالهجرةِ لإقامةِ الدين، وحتميّةُ الموت، وغرفُ الجنّةِ للصابرين المتوكّلين، وتكفّلُ الله بالرزق، وإقرارُ المشركين بالخالق، وحقيقةُ الدنيا والآخرة، وإخلاصُهم عند الشدّة، ونعمةُ الأمن، وهدايةُ المجاهدين","verses":[{"n":56,"reflection":{"text":"«يا عبادي الذين آمنوا إن أرضي واسعة فإياي فاعبدون» — يا عبادي المؤمنين إنّ أرضي واسعةٌ فهاجروا إن مُنِعتم من عبادتي، فإياي وحدي فاعبدون؛ ففي هذا الأمرُ بالهجرةِ لإقامةِ الدينِ وإخلاصِ العبادة؛ فإن ضاق بك موطنٌ عن عبادةِ الله فاطلب سعةَ أرضه، فأرضُ الله واسعة، والغايةُ عبادتُه حيثما كنت، فلا تؤثر وطنًا على دينك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الهجرةُ لإقامةِ الدين، وإخلاصُ العبادةِ لله."},"action":{"text":"إن مُنِعت من عبادةِ الله وإقامةِ دينك في موطنٍ، أو خشيت الفتنةَ في دينك، فاطلب سعةَ أرضِ الله بالهجرةِ إلى حيث تعبده آمنًا «إن أرضي واسعة فإياي فاعبدون»؛ فأرضُ الله واسعة، والغايةُ عبادتُه وحده حيثما حللت؛ فلا تؤثر البقاءَ في موطنِ الفتنةِ على سلامةِ دينك؛ واجعل عبادةَ الله وإخلاصها غايتك أينما كنت؛ فمن ترك أرضًا لله عوّضه خيرًا منها؛ فقدّم دينك على وطنك ومألوفك إن تعارضا؛ فالمقصودُ عبادةُ الله، وهي ممكنةٌ في سعةِ أرضه؛ فلا تجعل ضيقَ المكانِ عذرًا لترْكِ الدين."}},{"n":57,"reflection":{"text":"«كل نفس ذائقة الموت ثم إلينا ترجعون» — كلُّ نفسٍ ذائقةُ الموتِ لا محالة، ثم إلينا تُرجَعون للحساب؛ ففي هذا تذكيرٌ بحتميّةِ الموتِ والرجوعِ إلى الله؛ فاستحضر الموتَ والرجوعَ إلى الله، فمن أيقن بالموتِ استعدَّ له، ولم تفتنه الدنيا، فكلُّنا راحلٌ، والموفَّقُ من تزوّد لآخرته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ الموتِ والرجوعِ إلى الله والاستعدادُ لهما."},"action":{"text":"استحضر دائمًا أنّ الموتَ حتمٌ لا مفرَّ منه، وأنك راجعٌ إلى الله للحساب «كل نفس ذائقة الموت ثم إلينا ترجعون»؛ فأكثر من ذكرِ الموتِ، فإنه يهوّن عليك الدنيا، ويحملك على الاستعدادِ للآخرة؛ فلا تفتنك الحياةُ الدنيا فتغفل عن رحيلك؛ فمن أيقن بالموتِ والرجوعِ إلى الله تزوّد بالعملِ الصالح، ولم يركن إلى الفاني؛ فاجعل الموتَ واعظك، والرجوعَ إلى الله همّك؛ فبادر بالتوبةِ والعملِ قبل أن يفجأك الأجل؛ فالكيّسُ من دان نفسه وعمل لما بعد الموت، والعاجزُ من أتبع نفسه هواها وتمنّى على الله."}},{"n":58,"reflection":{"text":"«والذين آمنوا وعملوا الصالحات لنبوئنهم من الجنة غرفا تجري من تحتها الأنهار خالدين فيها نعم أجر العاملين» — والذين آمنوا وعملوا الصالحاتِ لننزلنّهم من الجنّةِ غرفًا عاليةً تجري من تحتها الأنهارُ خالدين فيها، نعم أجرُ العاملين؛ ففي هذا جزاءُ المؤمنين العاملين بالجنّة؛ فاعمل الصالحاتِ طمعًا في غرفِ الجنّةِ الخالدة، فنعم الأجرُ لمن عمل، فاجعل عملك سبيلك إلى تلك الغرفِ العالية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ طمعًا في غرفِ الجنّةِ الخالدة."},"action":{"text":"اعمل الصالحاتِ مع صدقِ الإيمان، طمعًا في نزولِ الغرفِ العاليةِ في الجنّةِ التي تجري من تحتها الأنهار، خالدًا فيها «لنبوئنهم من الجنة غرفا»؛ فنعم الأجرُ لمن عمل الصالحات؛ فاجعل هذا الجزاءَ العظيمَ حافزًا لك على الاجتهادِ في الطاعة؛ فلا تحقر عملًا صالحًا، ولا تكسل عن قربة؛ فكلُّ عملٍ لبنةٌ في غرفتك؛ فبادر بالخيرات، وسابق إليها، مبتغيًا وجهَ الله وثوابه؛ فمن عمل لله بإيمانٍ وإخلاصٍ نال أعلى المنازل؛ فالجنّةُ سلعةُ الله الغالية، ثمنُها الإيمانُ والعملُ الصالح."}},{"n":59,"reflection":{"text":"«الذين صبروا وعلى ربهم يتوكلون» — هم الذين صبروا على الطاعاتِ والمصائب، وعلى ربّهم وحده يتوكّلون؛ ففي هذا أنّ الصبرَ والتوكّلَ سبيلُ نيلِ الجزاء؛ فتحلَّ بالصبرِ والتوكّل، فبهما تُنال غرفُ الجنّة، فالصابرُ المتوكّلُ هو الفائز، فاصبر على الطاعةِ والبلاء، وتوكّل على ربّك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التحلّي بالصبرِ والتوكّلِ لنيلِ الجزاء."},"action":{"text":"تحلَّ بالصبرِ على الطاعاتِ وعن المعاصي وعلى المصائب، وبالتوكّلِ على الله وحده في كلِّ أمورك؛ فهاتان الصفتان صفتا أهلِ الغرفِ العالية «الذين صبروا وعلى ربهم يتوكلون»؛ فاصبر صبرًا جميلًا عند البلاء، وواظب على الطاعةِ ولو شقّت، واكفف عن المعصيةِ ولو اشتهتها النفس؛ وفوّض أمرك إلى الله معتمدًا عليه آخذًا بالأسباب؛ فبالصبرِ والتوكّلِ تُنال أعلى الدرجات؛ فمن صبر ظفر، ومن توكّل كُفِي؛ فاجعلهما زادك في طريقك إلى الله؛ فبهما يهون كلُّ صعب، ويُدرَك كلُّ خير."}},{"n":60,"reflection":{"text":"«وكأين من دابة لا تحمل رزقها الله يرزقها وإياكم وهو السميع العليم» — وكم من دابّةٍ ضعيفةٍ لا تدّخر رزقها ولا تقدر على حمله، الله يرزقها ويرزقكم، وهو السميعُ العليم؛ ففي هذا أنّ الرزقَ بيدِ الله فلا يُترَك الدينُ خوفَ الفقر؛ فلا تخف الفقرَ فتترك الهجرةَ أو الطاعة، فمن رزق الدوابَّ العاجزةَ لا يعجز عن رزقك، فاطمئنَّ إلى تكفّلِ الله بالرزق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"الطمأنينةُ إلى تكفّلِ الله بالرزقِ وعدمُ خوفِ الفقر."},"action":{"text":"اطمئنَّ إلى أنّ الله تكفّل برزقك، فلا تخف الفقرَ فتترك هجرةً في سبيله أو طاعةً أو حقًّا؛ فمن يرزق الدوابَّ الضعيفةَ التي لا تقدر على ادّخارِ رزقها لا يعجز عن رزقك «الله يرزقها وإياكم»؛ فهو السميعُ لدعائك، العليمُ بحاجتك؛ فاطلب الرزقَ من الحلال، وتوكّل على الله، ولا يحملك الحرصُ أو الخوفُ على معصيةٍ أو ترْكِ واجب؛ فالرزقُ مقسومٌ لا يزيده حرصٌ ولا ينقصه تقوى؛ فاجعل همّك طاعةَ الله، وثِق بأنه لن يضيّعك؛ فمن اتّقى الله رزقه من حيث لا يحتسب."}},{"n":61,"reflection":{"text":"«ولئن سألتهم من خلق السماوات والأرض وسخر الشمس والقمر ليقولن الله فأنى يؤفكون» — ولئن سألت المشركين من خلق السماواتِ والأرضَ وسخّر الشمسَ والقمرَ ليقولنّ الله، فكيف يُصرَفون عن عبادته؟ ففي هذا إقرارُهم بربوبيةِ الله مع شركهم في العبادة؛ فاعلم أنّ الإقرارَ بالخالقِ يوجب إفرادَه بالعبادة، فمن أقرّ بأنّ الله الخالقُ فليعبده وحده، فالتناقضُ أن تقرَّ بالربّ وتعبد سواه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الإقرارَ بالخالقِ يوجب إفرادَه بالعبادة."},"action":{"text":"اعلم أنّ الإقرارَ بأنّ الله وحده خالقُ السماواتِ والأرضِ ومسخّرُ الشمسِ والقمرِ يوجب إفرادَه بالعبادةِ والتأله؛ فالمشركون أقرّوا بربوبيته «ليقولن الله» ثم أشركوا في عبادته، وهذا تناقضٌ عجيب «فأنى يؤفكون»؛ فحقّق التوحيدَ بنوعيه: توحيدَ الربوبيةِ وتوحيدَ الألوهية؛ فمن أقرّ بأنّ الله خالقه ورازقه ومدبّرُ أمره، فليخصّه بالعبادةِ والدعاءِ والخوفِ والرجاء؛ فلا تعبد مع الخالقِ مخلوقًا؛ فالعبادةُ حقٌّ للخالقِ وحده؛ فاجعل إقرارك بربوبيةِ الله حاملًا لك على إخلاصِ العبادةِ له."}},{"n":62,"reflection":{"text":"«الله يبسط الرزق لمن يشاء من عباده ويقدر له إن الله بكل شيء عليم» — الله يوسّع الرزقَ لمن يشاء ويضيّقه على من يشاء بحكمته، إنّ الله بكلِّ شيءٍ عليم؛ ففي هذا أنّ بسطَ الرزقِ وقبضه بحكمةِ الله وعلمه؛ فارضَ بقسمةِ الله لك، فبسطُ الرزقِ وقبضه بعلمٍ وحكمة، لا لكرامةٍ ولا هوان، فلا تحزن على قلّةٍ ولا تبطر بكثرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بقسمةِ الله في الرزقِ بسطًا وقبضًا."},"action":{"text":"ارضَ بقسمةِ الله لك في الرزقِ، فهو يبسطه لمن يشاء ويقدره على من يشاء بحكمته وعلمه المحيط «الله يبسط الرزق لمن يشاء من عباده ويقدر له»؛ فلا تحزن على قلّةِ رزقٍ فتظنّه هوانًا، ولا تبطر بكثرته فتظنّه كرامة؛ فكلاهما ابتلاءٌ واختبار؛ فاشكر عند البسط، واصبر عند القبض؛ ولا تحسد أحدًا على ما آتاه الله؛ فبسطُ الرزقِ وقبضه بعلمِ الله وحكمته لا جزافًا؛ فمن رضي بقسمةِ الله أراحه، ومن سخط أتعب نفسه ولم ينل إلا ما قُدِّر له؛ فاطمئنَّ إلى حكمةِ الرزّاقِ العليم."}},{"n":63,"reflection":{"text":"«ولئن سألتهم من نزل من السماء ماء فأحيا به الأرض من بعد موتها ليقولن الله قل الحمد لله بل أكثرهم لا يعقلون» — ولئن سألت المشركين من نزّل الماءَ فأحيا به الأرضَ بعد موتها ليقولنّ الله، قل: الحمدُ لله، بل أكثرهم لا يعقلون تناقضهم؛ ففي هذا إقامةُ الحجّةِ عليهم بإحياءِ الأرض، والحمدُ لله على ظهورِ الحجّة؛ فتأمّل إحياءَ الأرضِ بالماء، فمن أحياها قادرٌ على إحيائك بعد الموت، فاحمد الله، وأيقن بالبعث.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في إحياءِ الأرضِ دليلًا على البعثِ وحمدُ الله."},"action":{"text":"تأمّل كيف ينزّل الله الماءَ من السماءِ فيحيي به الأرضَ بعد موتها؛ فذلك برهانٌ على قدرته على إحيائك بعد الموت والبعث «فأحيا به الأرض من بعد موتها»؛ فمن أحيا الأرضَ الميّتةَ قادرٌ على إحياءِ الموتى؛ فاحمد الله على وضوحِ الحجّة وظهورِ الآية «قل الحمد لله»؛ ورسّخ يقينك بالبعثِ بالنظرِ في هذه الآيةِ المتكرّرةِ أمامك كلَّ عام؛ فلا تكن من الأكثرِ الذين لا يعقلون فيرون الآيةَ ولا يعتبرون؛ بل كن ممّن يتفكّر في خلقِ الله فيزداد إيمانًا وحمدًا وتعظيمًا؛ فالكونُ شاهدٌ على البعثِ لمن عقل."}},{"n":64,"reflection":{"text":"«وما هذه الحياة الدنيا إلا لهو ولعب وإن الدار الآخرة لهي الحيوان لو كانوا يعلمون» — وما هذه الحياةُ الدنيا إلا لهوٌ ولعبٌ زائل، وإنّ الدارَ الآخرةَ لهي الحياةُ الحقيقيةُ الدائمة، لو كانوا يعلمون؛ ففي هذا حقيقةُ الدنيا وحقيقةُ الآخرة؛ فلا تغترَّ بالدنيا فإنها لهوٌ زائل، واعمل للآخرةِ فإنها الحياةُ الحقّة، فالعاقلُ من عمل للدارِ الباقيةِ لا للفانية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ حقيقةِ الدنيا الزائلةِ والعملُ للآخرةِ الباقية."},"action":{"text":"اعرف حقيقةَ الدنيا: أنها لهوٌ ولعبٌ زائلٌ سريعُ الانقضاء؛ وحقيقةَ الآخرة: أنها الحياةُ الحقيقيةُ الدائمةُ التي لا موتَ بعدها «وإن الدار الآخرة لهي الحيوان»؛ فلا تغترَّ بزينةِ الدنيا ولذّاتها فتجعلها أكبرَ همّك؛ بل اجعلها مزرعةً لآخرتك، ووسيلةً لا غاية؛ واعمل للدارِ الباقيةِ عملَ من يعلم أنها الحياةُ الحقّة؛ فالعاقلُ من آثر الباقيَ على الفاني، والجاهلُ من باع آخرته بدنياه؛ فوازن بين الدارين، واجعل سعيك الأكبرَ للآخرة؛ فمن عمل لها ربح، ومن آثر الدنيا عليها خسر الحياةَ الحقيقية."}},{"n":65,"reflection":{"text":"«فإذا ركبوا في الفلك دعوا الله مخلصين له الدين فلما نجاهم إلى البر إذا هم يشركون» — فإذا ركبوا السفنَ وخافوا الغرقَ دعوا الله مخلصين له الدين، فلما نجّاهم إلى البرِّ إذا هم يشركون؛ ففي هذا فطرةُ الإخلاصِ عند الشدّةِ ونكوصُهم عند الرخاء؛ فأخلص لله في الرخاءِ كما في الشدّة، ولا تكن ممّن يذكر الله عند الكربِ وينساه عند العافية، فالمؤمنُ مخلصٌ في كلِّ حال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ لله في الرخاءِ كما في الشدّة."},"action":{"text":"أخلص عبادتك ودعاءك لله في الرخاءِ كما تخلص له في الشدّة، ولا تكن كالمشركين الذين يخلصون له عند الكربِ ثم يشركون عند النجاة «فلما نجاهم إلى البر إذا هم يشركون»؛ فالمؤمنُ الصادقُ يذكر الله في السرّاءِ والضرّاء، ويعبده في العسرِ واليسر؛ فراقب نفسك: أتذكر الله في عافيتك كما تذكره في بلائك؟ فاحذر أن تلجأ إليه عند الحاجةِ وتنساه عند الغنى؛ فالوفاءُ أن تعبده في كلِّ حال؛ فمن أخلص له في الرخاءِ نجّاه في الشدّة؛ فاجعل إخلاصك دائمًا لا موسميًّا؛ فذلك حقيقةُ التوحيدِ وثمرةُ الإيمان."}},{"n":66,"reflection":{"text":"«ليكفروا بما آتيناهم وليتمتعوا فسوف يعلمون» — ليجحدوا نعمةَ النجاةِ التي آتيناهم وليتمتّعوا بدنياهم، فسوف يعلمون عاقبةَ كفرهم؛ ففي هذا تهديدٌ لمن كفر النعمةَ وآثر التمتّع؛ فاحذر كفرانَ نعمِ الله والانشغالَ بالتمتّعِ عن الشكر، فمن كفر النعمةَ وآثر اللذّةَ سيعلم سوءَ عاقبته، فاشكر النعمَ ولا تكفرها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من كفرانِ النعمةِ وإيثارِ التمتّعِ على الشكر."},"action":{"text":"احذر كفرانَ نعمِ الله والانشغالَ بالتمتّعِ بها عن شكرِ المنعم، فذلك سبيلُ من توعّدهم الله «ليكفروا بما آتيناهم وليتمتعوا فسوف يعلمون»؛ فقابل كلَّ نعمةٍ بالشكرِ لا بالبطرِ والغفلة؛ فاستعمل نعمَ الله في طاعته لا في معصيته؛ فمن شكر النعمةَ حفظها الله عليه وزاده، ومن كفرها وآثر اللذّةَ العاجلةَ سيعلم سوءَ عاقبته حين لا ينفع العلم؛ فلا تجعل نعمَ الله سببًا لغفلتك عنه؛ بل اجعلها سلّمًا لشكره وطاعته؛ فالنعمُ تُستبقى بالشكرِ وتُستجلَب بالطاعة، وتُمحق بالكفرانِ والبطر."}},{"n":67,"reflection":{"text":"«أولم يروا أنا جعلنا حرما آمنا ويتخطف الناس من حولهم أفبالباطل يؤمنون وبنعمة الله يكفرون» — أولم يروا أنا جعلنا لهم حرمًا آمنًا (مكةَ) والناسُ يُخطَفون من حولهم؟ أفبالباطلِ يؤمنون وبنعمةِ الله يكفرون؟ ففي هذا تذكيرٌ بنعمةِ الأمنِ وتوبيخٌ على كفرها؛ فاشكر نعمةَ الأمنِ التي تعيشها، ولا تكفرها بالإعراضِ عن المنعم، فنعمةُ الأمنِ من أعظمِ النعمِ التي تستوجب الشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الأمنِ وعدمُ كفرانها بالإعراض."},"action":{"text":"اشكر نعمةَ الأمنِ التي تعيشها في وطنك ومسكنك، فهي من أعظمِ نعمِ الله التي غفل عنها كثيرٌ من الناس «أولم يروا أنا جعلنا حرما آمنا»؛ فكم من بلادٍ يُخطَف أهلها ويُقتَّلون وأنت في أمنٍ وطمأنينة؛ فلا تكفر هذه النعمةَ بالإعراضِ عن الله أو الإيمانِ بالباطلِ والكفرِ بالحقّ «أفبالباطل يؤمنون وبنعمة الله يكفرون»؛ فقابل نعمةَ الأمنِ بالشكرِ والطاعةِ وإخلاصِ العبادة؛ فمن شكر الأمنَ دام له، ومن كفره عرّضه للزوال؛ فاحمد الله على أمنك، واستعمله في طاعته، ولا تجعله سبيلًا للغفلةِ والبطر."}},{"n":68,"reflection":{"text":"«ومن أظلم ممن افترى على الله كذبا أو كذب بالحق لما جاءه أليس في جهنم مثوى للكافرين» — ولا أحدَ أظلمُ ممّن اختلق على الله كذبًا أو كذّب بالحقِّ حين جاءه، أليس في جهنمَ مقامٌ للكافرين؟ ففي هذا أنّ الافتراءَ على الله وتكذيبَ الحقِّ من أعظمِ الظلم؛ فاحذر أن تفتري على الله أو تكذّب بالحقّ، فذلك غايةُ الظلمِ وموجبُ النار، فالزم الصدقَ على الله وقبولَ الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الافتراءِ على الله وتكذيبِ الحق."},"action":{"text":"احذر أشدَّ الحذرِ من الافتراءِ على الله بأن تنسب إليه ما لم يقل، أو تقول في دينه بلا علم، أو تحلّل وتحرّم بهواك؛ واحذر من تكذيبِ الحقِّ حين يأتيك ويتبيّن لك؛ فهذان من أعظمِ الظلمِ وموجباتِ النار «ومن أظلم ممن افترى على الله كذبا أو كذب بالحق لما جاءه»؛ فالزم الصدقَ فيما تنسبه إلى الله، ولا تقل عليه إلا بعلم؛ واقبل الحقَّ متى جاءك ولا تعانده؛ فمن افترى على الله أو كذّب بالحقِّ فمثواه جهنم؛ فعظّم حقَّ الله في القولِ عليه، وحقَّ الحقِّ في قبوله؛ فبهما تنجو من هذا الظلمِ العظيم."}},{"n":69,"reflection":{"text":"«والذين جاهدوا فينا لنهدينهم سبلنا وإن الله لمع المحسنين» — والذين جاهدوا أنفسهم وأعداءهم في سبيلنا لنهدينّهم سبلنا وطرقَ الخيرِ الموصلةَ إلينا، وإنّ الله لمع المحسنين بالعونِ والتأييد؛ ففي هذا أنّ الجهادَ والمجاهدةَ سببُ الهداية، وأنّ الإحسانَ سببُ معيّةِ الله؛ فجاهد نفسك في طاعةِ الله يزدك هدى، وأحسن عملك تنل معيّةَ الله، فالهدى ثمرةُ المجاهدة، والمعيّةُ ثمرةُ الإحسان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المجاهدةُ في سبيلِ الله سببٌ للهدايةِ والمعيّة."},"action":{"text":"جاهد نفسك وهواك وشيطانك في طاعةِ الله وطلبِ مرضاته، فإنّ الله وعد المجاهدين بزيادةِ الهدايةِ وفتحِ سبلِ الخيرِ لهم «والذين جاهدوا فينا لنهدينهم سبلنا»؛ فكلّما جاهدت نفسك على الطاعةِ زادك الله هدًى وبصيرةً وتوفيقًا؛ وأحسن عملك وعبادتك ومعاملتك، فإنّ الله مع المحسنين بالعونِ والتأييدِ والحفظِ والنصر «وإن الله لمع المحسنين»؛ فاجعل المجاهدةَ والإحسانَ دأبك؛ فالهدى ثمرةُ المجاهدة، ومعيّةُ الله الخاصّةُ ثمرةُ الإحسان؛ فمن جاهد هُدِي، ومن أحسن نال معيّةَ الله؛ فاختم سورتك بعزمٍ صادقٍ على مجاهدةِ نفسك وإحسانِ عملك؛ فذلك سبيلُ الوصولِ إلى الله."}}]}],"coverage":{"covered":69,"total":69}};
